/**
 * History service facade.
 *
 * Endpoint reference: web-bff/api/v1/history
 */

import { type HistoryFilters, type HistoryExportOptions } from '../../models/History';
import { historyEndpoint } from './endpoint';

export const historyService = {
  getHistory: (filters?: HistoryFilters, page = 1, pageSize = 20) =>
    historyEndpoint.getHistory(filters, page, pageSize),

  getStats: () => historyEndpoint.getStats(),

  exportReport: (options: HistoryExportOptions) => historyEndpoint.exportReport(options),

  getHistoryItem: (id: string) => historyEndpoint.getHistoryItem(id),
};
