import React from 'react';
import { useAlert } from '../../common/Alert';
import { PendingApproval } from '../../../models/ManagerDashboard';
import styles from './PendingApprovals.module.css';

interface PendingApprovalsProps {
  approvals: PendingApproval[];
  maxItems?: number;
  onApprove?: (approvalId: string) => void;
  onReject?: (approvalId: string) => void;
  onClose?: (approvalId: string) => void;
  onReopen?: (approvalId: string) => void;
}

export const PendingApprovals: React.FC<PendingApprovalsProps> = ({
  approvals,
  maxItems = 5,
  onApprove,
  onReject,
  onClose,
  onReopen,
}) => {
  const alert = useAlert();
  const displayedApprovals = approvals.slice(0, maxItems);

  const handleApprove = (approvalId: string) => {
    alert.confirm(
      'Bạn có chắc chắn muốn phê duyệt công việc này?',
      () => {
        onApprove?.(approvalId);
      }
    );
  };

  const handleReject = (approvalId: string) => {
    alert.confirm(
      'Bạn có chắc chắn muốn từ chối công việc này?',
      () => {
        onReject?.(approvalId);
      }
    );
  };

  const handleClose = (approvalId: string) => {
    alert.confirm(
      'Bạn có chắc chắn muốn đóng công việc này?',
      () => {
        onClose?.(approvalId);
      }
    );
  };

  const handleReopen = (approvalId: string) => {
    alert.confirm(
      'Bạn có chắc chắn muốn mở lại công việc này?',
      () => {
        onReopen?.(approvalId);
      }
    );
  };

  return (
    <div className={styles.pendingApprovals}>
      <div className={styles.approvalsList}>
        {displayedApprovals.map((approval) => (
          <div
            key={approval.id}
            className={styles.approvalCard}
            style={{ borderLeftColor: `var(--${approval.borderColor})` }}
          >
            {/* Header */}
            <div className={styles.approvalHeader}>
              <div className={styles.approvalInfo}>
                <div className={styles.approvalTitle}>
                  {approval.code}: {approval.title}
                </div>
                <div className={styles.submittedBy}>
                  by {approval.submittedBy}
                </div>
              </div>
              <span
                className={`${styles.badge} ${
                  styles[approval.statusBadge.variant]
                }`}
              >
                {approval.statusBadge.text}
              </span>
            </div>

            {/* Content */}
            <div className={styles.approvalContent}>
              {approval.status === 'review' && approval.progress !== undefined ? (
                <>
                  <div className={styles.progressLabel}>
                    Progress: {approval.progress}%
                  </div>
                  <div className={styles.progressBar}>
                    <div
                      className={styles.progressFill}
                      style={{ width: `${approval.progress}%` }}
                    />
                  </div>
                </>
              ) : (
                <div className={styles.description}>{approval.description}</div>
              )}
            </div>

            {/* Actions */}
            <div className={styles.approvalActions}>
              {approval.status === 'review' ? (
                <>
                  <button
                    className={`${styles.btn} ${styles.btnSuccess}`}
                    onClick={() => handleApprove(approval.id)}
                  >
                    <i className="fas fa-check" /> Approve
                  </button>
                  <button
                    className={`${styles.btn} ${styles.btnDanger}`}
                    onClick={() => handleReject(approval.id)}
                  >
                    <i className="fas fa-times" /> Reject
                  </button>
                </>
              ) : (
                <>
                  <button
                    className={`${styles.btn} ${styles.btnSuccess}`}
                    onClick={() => handleClose(approval.id)}
                  >
                    <i className="fas fa-check" /> Đóng
                  </button>
                  <button
                    className={`${styles.btn} ${styles.btnSecondary}`}
                    onClick={() => handleReopen(approval.id)}
                  >
                    <i className="fas fa-redo" /> Mở lại
                  </button>
                </>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};
