import React from 'react';
import { Task } from '../../../../models/Task';
import { SubtaskState } from '../../types';
import { ChecklistItem } from './ChecklistItem';
import { AddSubtaskForm } from './AddSubtaskForm';
import styles from './ChecklistTab.module.css';

interface ChecklistTabProps {
  task: Task;
  editingSubtasks: Map<string, SubtaskState>;
  newSubtaskTitle: string;
  onToggleSubtask: (id: string) => Promise<void>;
  onAddSubtask: () => Promise<void>;
  onDeleteSubtask: (id: string) => Promise<void>;
  onStartEdit: (id: string, title: string) => void;
  onCancelEdit: (id: string) => void;
  onSaveEdit: (id: string) => Promise<void>;
  onEditTitleChange: (id: string, title: string) => void;
  onNewSubtaskChange: (title: string) => void;
  isProcessing?: boolean;
}

export const ChecklistTab: React.FC<ChecklistTabProps> = ({
  task,
  editingSubtasks,
  newSubtaskTitle,
  onToggleSubtask,
  onAddSubtask,
  onDeleteSubtask,
  onStartEdit,
  onCancelEdit,
  onSaveEdit,
  onEditTitleChange,
  onNewSubtaskChange,
  isProcessing = false,
}) => {
  const completedCount = task.subtasks?.filter((st) => st.completed).length || 0;
  const totalCount = task.subtasks?.length || 0;

  return (
    <div className={styles.cardBody}>
      <div className={styles.section}>
        <div className={styles.sectionTitle}>
          <i className="fas fa-tasks"></i> Checklist ({completedCount}/{totalCount} completed)
        </div>
        <div className={styles.checklist}>
          {/* Existing subtasks */}
          {task.subtasks && task.subtasks.length > 0 ? (
            task.subtasks.map((subtask) => {
              const editState = editingSubtasks.get(subtask.id);
              const isEditing = editState?.isEditing || false;

              return (
                <ChecklistItem
                  key={subtask.id}
                  subtask={subtask}
                  isEditing={isEditing}
                  editTitle={editState?.title}
                  onToggle={() => onToggleSubtask(subtask.id)}
                  onStartEdit={() => onStartEdit(subtask.id, subtask.title)}
                  onCancelEdit={() => onCancelEdit(subtask.id)}
                  onSaveEdit={() => onSaveEdit(subtask.id)}
                  onDelete={() => onDeleteSubtask(subtask.id)}
                  onEditTitleChange={(title) => onEditTitleChange(subtask.id, title)}
                  disabled={isProcessing}
                />
              );
            })
          ) : (
            <div className={styles.emptyChecklist}>
              <i className="fas fa-tasks"></i>
              <p>Chưa có subtask nào. Thêm mới để bắt đầu!</p>
            </div>
          )}

          {/* Add new subtask form */}
          <AddSubtaskForm
            value={newSubtaskTitle}
            onChange={onNewSubtaskChange}
            onAdd={onAddSubtask}
            disabled={isProcessing}
          />
        </div>
      </div>
    </div>
  );
};
