/**
 * StatisticsPage Component
 * Main container for Personal Statistics & Analytics
 */

import React, { useState, useEffect } from 'react';
import { StatisticsPeriod, type StatisticsData, type GoalsData, type AchievementsData } from '../../models/Statistics';
import { statisticsService } from '../../services/statisticsService';
import { useAppToast } from '../../hooks/useAppToast';
import { PeriodSelector } from '../../components/statistics/PeriodSelector';
import { PerformanceCards } from '../../components/statistics/PerformanceCards';
import { PerformanceScore } from '../../components/statistics/PerformanceScore';
import { TrendsChart } from '../../components/statistics/TrendsChart';
import { PriorityChart } from '../../components/statistics/PriorityChart';
import { CategoryDistribution } from '../../components/statistics/CategoryDistribution';
import { MonthlyComparison } from '../../components/statistics/MonthlyComparison';
import { InsightsPanel } from '../../components/statistics/InsightsPanel';
import { PersonalGoals } from '../../components/statistics/PersonalGoals';
import { AchievementsBadges } from '../../components/statistics/AchievementsBadges';
import { TeamComparison } from '../../components/statistics/TeamComparison';
import { Button } from '../../components/common';
import styles from './StatisticsPage.module.css';

const StatisticsPage: React.FC = () => {
  const toast = useAppToast();
  const [period, setPeriod] = useState<StatisticsPeriod>(StatisticsPeriod.Month);
  const [statistics, setStatistics] = useState<StatisticsData | null>(null);
  const [goals, setGoals] = useState<GoalsData | null>(null);
  const [achievements, setAchievements] = useState<AchievementsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadStatistics();
  }, [period]);

  useEffect(() => {
    loadGoals();
    loadAchievements();
  }, []);

  const loadStatistics = async () => {
    try {
      setLoading(true);
      const data = await statisticsService.getStatistics(period);
      setStatistics(data);
      setError(null);
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể tải dữ liệu thống kê');
      setError('Không thể tải dữ liệu thống kê');
    } finally {
      setLoading(false);
    }
  };

  const loadGoals = async () => {
    try {
      const data = await statisticsService.getGoals();
      setGoals(data);
    } catch (err: unknown) {
      console.warn('[StatisticsPage] Failed to load goals:', err);
    }
  };

  const loadAchievements = async () => {
    try {
      const data = await statisticsService.getAchievements();
      setAchievements(data);
    } catch (err: unknown) {
      console.warn('[StatisticsPage] Failed to load achievements:', err);
    }
  };

  const handleExportReport = async () => {
    try {
      const blob = await statisticsService.exportReport(period);
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `statistics-report-${period}.pdf`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể xuất báo cáo, vui lòng thử lại');
    }
  };

  if (loading && !statistics) {
    return (
      <div className={styles.loading}>
        <i className="fas fa-spinner fa-spin"></i>
        <p>Đang tải dữ liệu...</p>
      </div>
    );
  }

  if (error || !statistics) {
    return (
      <div className={styles.error}>
        <i className="fas fa-exclamation-circle"></i>
        <p>{error || 'Không thể tải dữ liệu'}</p>
        <button onClick={loadStatistics} className={styles.retryButton}>
          <i className="fas fa-redo"></i> Thử lại
        </button>
      </div>
    );
  }

  return (
    <div className={styles.statisticsPage}>
      {/* Page Header */}
      <div className={styles.pageHeader}>
        <div>
          <h1 className={styles.pageTitle}>
            <i className="fas fa-chart-line"></i>
            Thống kê Cá nhân
          </h1>
          <p className={styles.pageDescription}>
            Hiệu suất và thành tích công việc của bạn
          </p>
        </div>
        <div className={styles.pageActions}>
          <PeriodSelector value={period} onChange={setPeriod} />
          <Button variant="secondary" onClick={handleExportReport}>
            <i className="fas fa-download"></i> Export PDF
          </Button>
        </div>
      </div>

      {/* Performance Overview Cards */}
      <PerformanceCards data={statistics.performance} />

      {/* Trends and Performance Score */}
      <div className={styles.gridTwo}>
        <TrendsChart data={statistics.trends} />
        <PerformanceScore data={statistics.score} />
      </div>

      {/* AI Insights */}
      <InsightsPanel insights={statistics.insights} />

      {/* Priority and Category Distribution */}
      <div className={styles.gridTwo}>
        <PriorityChart data={statistics.priorityDistribution} />
        <CategoryDistribution data={statistics.categoryDistribution} />
      </div>

      {/* Monthly Comparison */}
      <MonthlyComparison data={statistics.monthlyComparison} />

      {/* Team Comparison */}
      <TeamComparison data={statistics.teamComparison} />

      {/* Personal Goals */}
      {goals && (
        <PersonalGoals goals={goals.goals} achievementRate={goals.achievementRate} />
      )}

      {/* Achievements & Badges */}
      {achievements && (
        <AchievementsBadges
          badges={achievements.badges}
          totalUnlocked={achievements.totalUnlocked}
          totalAvailable={achievements.totalAvailable}
        />
      )}
    </div>
  );
};

export default StatisticsPage;
