import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';
import { DashboardStats, WorkItem, ActivityItem, ScheduleItem } from '../../models/Dashboard';

interface DashboardState {
  stats: DashboardStats | null;
  workItems: WorkItem[];
  activities: ActivityItem[];
  schedule: ScheduleItem[];
  loading: boolean;
  error: string | null;
}

const initialState: DashboardState = {
  stats: null,
  workItems: [],
  activities: [],
  schedule: [],
  loading: false,
  error: null,
};

// Async thunks
export const fetchDashboardStats = createAsyncThunk(
  'dashboard/fetchStats',
  async () => {
    // TODO: Replace with actual API call when dashboard endpoint is available
    // const response = await fetch('/api/dashboard/staff/stats');
    // return await response.json();
    return {} as DashboardStats;
  }
);

export const fetchMyWork = createAsyncThunk(
  'dashboard/fetchMyWork',
  async () => {
    // TODO: Replace with actual API call when dashboard endpoint is available
    // const response = await fetch('/api/dashboard/staff/work');
    // return await response.json();
    return [] as WorkItem[];
  }
);

export const fetchRecentActivity = createAsyncThunk(
  'dashboard/fetchRecentActivity',
  async () => {
    // TODO: Replace with actual API call when dashboard endpoint is available
    // const response = await fetch('/api/dashboard/staff/activity');
    // return await response.json();
    return [] as ActivityItem[];
  }
);

export const fetchTodaysSchedule = createAsyncThunk(
  'dashboard/fetchTodaysSchedule',
  async () => {
    // TODO: Replace with actual API call when dashboard endpoint is available
    // const response = await fetch('/api/dashboard/staff/deadlines');
    // return await response.json();
    return [] as ScheduleItem[];
  }
);

export const fetchAllDashboardData = createAsyncThunk(
  'dashboard/fetchAll',
  async (_, { dispatch }) => {
    // Fetch all dashboard data in parallel
    await Promise.all([
      dispatch(fetchDashboardStats()),
      dispatch(fetchMyWork()),
      dispatch(fetchRecentActivity()),
      dispatch(fetchTodaysSchedule()),
    ]);
  }
);

// Slice
const dashboardSlice = createSlice({
  name: 'dashboard',
  initialState,
  reducers: {
    clearDashboard: (state) => {
      state.stats = null;
      state.workItems = [];
      state.activities = [];
      state.schedule = [];
      state.error = null;
    },
    updateStats: (state, action: PayloadAction<Partial<DashboardStats>>) => {
      if (state.stats) {
        state.stats = { ...state.stats, ...action.payload };
      }
    },
    addActivity: (state, action: PayloadAction<ActivityItem>) => {
      state.activities.unshift(action.payload);
      // Keep only the last 10 activities
      if (state.activities.length > 10) {
        state.activities = state.activities.slice(0, 10);
      }
    },
  },
  extraReducers: (builder) => {
    // Fetch Dashboard Stats
    builder
      .addCase(fetchDashboardStats.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchDashboardStats.fulfilled, (state, action) => {
        state.loading = false;
        state.stats = action.payload;
      })
      .addCase(fetchDashboardStats.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch dashboard stats';
      });

    // Fetch My Work
    builder
      .addCase(fetchMyWork.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchMyWork.fulfilled, (state, action) => {
        state.loading = false;
        state.workItems = action.payload;
      })
      .addCase(fetchMyWork.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch work items';
      });

    // Fetch Recent Activity
    builder
      .addCase(fetchRecentActivity.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchRecentActivity.fulfilled, (state, action) => {
        state.loading = false;
        state.activities = action.payload;
      })
      .addCase(fetchRecentActivity.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch recent activity';
      });

    // Fetch Today's Schedule
    builder
      .addCase(fetchTodaysSchedule.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchTodaysSchedule.fulfilled, (state, action) => {
        state.loading = false;
        state.schedule = action.payload;
      })
      .addCase(fetchTodaysSchedule.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch schedule';
      });

    // Fetch All Dashboard Data
    builder
      .addCase(fetchAllDashboardData.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchAllDashboardData.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(fetchAllDashboardData.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch dashboard data';
      });
  },
});

export const { clearDashboard, updateStats, addActivity } = dashboardSlice.actions;
export default dashboardSlice.reducer;
