/**
 * useMessages — shared hook for unified messaging (chat + comments).
 *
 * Reusable for BOTH TaskDetailPage and TicketDetailPage.
 * Replaces the old useTaskComments hook and inline TicketTabs logic.
 *
 * Usage:
 *   const msgs = useMessages('task', taskId);
 *   const msgs = useMessages('ticket', ticketId);
 */

import { useCallback, useEffect, useMemo, useState } from 'react';
import { ChatMessage } from '../components/shared/ChatTab';
import { Comment } from '../components/shared/CommentsTab';
import { UUID } from '../models/common';
import {
  messageService,
  BffMessageDto,
  mapToChat,
  mapToComment,
  buildCommentTree,
} from '../services/message';
import {
  signalRService,
  useSignalREvent,
  HubMethod,
  NewMessageEvent,
  MessageEditedEvent,
  MessageDeletedEvent,
  HubEvent,
} from '../services/signalr';

interface UseMessagesReturn {
  /** Flat chat messages (for ChatTab) — filtered type='message' */
  chatMessages: ChatMessage[];
  /** Threaded comments (for CommentsTab) — filtered type='comment', tree-built */
  comments: Comment[];
  /** True while initial reload is in progress */
  loading: boolean;
  /** Error message */
  error: string | null;
  /** Server total count of chat messages (for chat tab badge) */
  chatCount: number;
  /** Server total count of comments (for comments tab badge) */
  commentCount: number;
  /** Whether there are more chat messages to load */
  hasMoreChat: boolean;
  /** Whether there are more comments to load */
  hasMoreComments: boolean;
  /** Reload all messages from server (resets both pages to 1) */
  reload: () => Promise<void>;
  /** Load older chat messages (prepends) */
  loadMoreChat: () => Promise<void>;
  /** Load older comments (prepends) */
  loadMoreComments: () => Promise<void>;
  /** Send a chat-style message (creates type='message') */
  sendMessage: (content: string) => Promise<void>;
  /** Add a comment, optionally threaded (creates type='comment') */
  addComment: (content: string, parentId?: UUID) => Promise<void>;
  /** Edit an existing message/comment */
  editComment: (messageId: UUID, content: string) => Promise<void>;
  /** Delete a message/comment */
  deleteComment: (messageId: UUID) => Promise<void>;
}

const hubJoinMethod = (entityType: string) =>
  entityType === 'ticket' ? HubMethod.JoinTicketRoom : HubMethod.JoinTaskRoom;
const hubLeaveMethod = (entityType: string) =>
  entityType === 'ticket' ? HubMethod.LeaveTicketRoom : HubMethod.LeaveTaskRoom;

export const useMessages = (
  entityType: 'ticket' | 'task',
  entityId: string | undefined,
): UseMessagesReturn => {
  // Raw BFF DTOs — split by type
  const [rawChat, setRawChat]         = useState<BffMessageDto[]>([]);
  const [rawComments, setRawComments] = useState<BffMessageDto[]>([]);
  const [loading, setLoading]         = useState(false);
  const [error, setError]             = useState<string | null>(null);

  // Per-type pagination pages
  const [chatPage, setChatPage]       = useState(1);
  const [commentPage, setCommentPage] = useState(1);

  // Server-side totals (all records, not just loaded) — kept accurate by SignalR deltas
  const [chatTotalCount, setChatTotal]       = useState(0);
  const [commentTotalCount, setCommentTotal] = useState(0);

  // Derived: whether more pages exist for each type independently
  const hasMoreChat     = useMemo(() => chatPage * 20 < chatTotalCount,    [chatPage, chatTotalCount]);
  const hasMoreComments = useMemo(() => commentPage * 20 < commentTotalCount, [commentPage, commentTotalCount]);

  // ── Fetch ──────────────────────────────────────────────────────────────

  const reload = useCallback(async () => {
    if (!entityId) return;
    setLoading(true);
    setError(null);
    setChatPage(1);
    setCommentPage(1);
    try {
      // Two independent type-scoped requests in parallel — each returns its own total
      const [chatRes, commentRes] = await Promise.all([
        messageService.getMessages(entityType, entityId, 'message', 1, 20),
        messageService.getMessages(entityType, entityId, 'comment', 1, 20),
      ]);
      // chatRes.chatTotalCount is the server total for chat messages (GROUP BY on page 1)
      setChatTotal(chatRes.chatTotalCount ?? chatRes.totalCount);
      setCommentTotal(commentRes.commentTotalCount ?? commentRes.totalCount);
      setRawChat(chatRes.items);
      setRawComments(commentRes.items);
    } catch (err) {
      console.error('[useMessages] Failed to fetch:', err);
      setError('Không thể tải dữ liệu');
    } finally {
      setLoading(false);
    }
  }, [entityType, entityId]);

  const loadMoreChat = useCallback(async () => {
    if (!entityId || !hasMoreChat) return;
    try {
      const nextPage = chatPage + 1;
      const response = await messageService.getMessages(entityType, entityId, 'message', nextPage, 20);
      setChatPage(nextPage);
      setRawChat((prev) => {
        const newItems = response.items.filter((m) => !prev.some((x) => x.id === m.id));
        return [...newItems, ...prev];
      });
    } catch (err) {
      console.error('[useMessages] Failed to load more chat:', err);
    }
  }, [entityType, entityId, hasMoreChat, chatPage]);

  const loadMoreComments = useCallback(async () => {
    if (!entityId || !hasMoreComments) return;
    try {
      const nextPage = commentPage + 1;
      const response = await messageService.getMessages(entityType, entityId, 'comment', nextPage, 20);
      setCommentPage(nextPage);
      setRawComments((prev) => {
        const newItems = response.items.filter((m) => !prev.some((x) => x.id === m.id));
        return [...newItems, ...prev];
      });
    } catch (err) {
      console.error('[useMessages] Failed to load more comments:', err);
    }
  }, [entityType, entityId, hasMoreComments, commentPage]);

  useEffect(() => {
    reload();
  }, [reload]);

  // ── SignalR: join / leave room ────────────────────────────────────────

  useEffect(() => {
    if (!entityId) return;
    let unmounted = false;

    const joinRoom = async () => {
      try {
        await signalRService.whenConnected();
        if (!unmounted) {
          await signalRService.invoke(hubJoinMethod(entityType), entityId);
          console.debug(`[useMessages] Joined ${entityType} room:`, entityId);
        }
      } catch (err) {
        console.warn('[useMessages] SignalR join failed:', err);
      }
    };
    joinRoom();

    // Re-join after auto-reconnect
    const unsubReconnect = signalRService.onReconnected(async () => {
      if (!unmounted) {
        await signalRService.invoke(hubJoinMethod(entityType), entityId);
        console.debug(`[useMessages] Re-joined ${entityType} room after reconnect:`, entityId);
      }
    });

    return () => {
      unmounted = true;
      unsubReconnect();
      signalRService.invoke(hubLeaveMethod(entityType), entityId).catch(() => {});
    };
  }, [entityType, entityId]);

  // ── SignalR: real-time events ─────────────────────────────────────────

  useSignalREvent(HubEvent.NewMessage, useCallback((e: NewMessageEvent) => {
    if (e.entityType !== entityType || e.entityId !== entityId) return;
    const m = e.message;
    if (m.type === 'message') {
      setRawChat((prev) => {
        if (prev.some((x) => x.id === m.id)) return prev;
        setChatTotal((c) => c + 1);
        return [...prev, m];
      });
    } else {
      setRawComments((prev) => {
        if (prev.some((x) => x.id === m.id)) return prev;
        setCommentTotal((c) => c + 1);
        return [...prev, m];
      });
    }
  }, [entityType, entityId]));

  useSignalREvent(HubEvent.MessageEdited, useCallback((e: MessageEditedEvent) => {
    if (e.entityType !== entityType || e.entityId !== entityId) return;
    const m = e.message;
    if (m.type === 'message') {
      setRawChat((prev) => prev.map((x) => (x.id === m.id ? m : x)));
    } else {
      setRawComments((prev) => prev.map((x) => (x.id === m.id ? m : x)));
    }
  }, [entityType, entityId]));

  useSignalREvent(HubEvent.MessageDeleted, useCallback((e: MessageDeletedEvent) => {
    if (e.entityType !== entityType || e.entityId !== entityId) return;
    setRawChat((prev) => {
      const next = prev.filter((x) => x.id !== e.messageId);
      if (next.length < prev.length) setChatTotal((c) => Math.max(0, c - 1));
      return next;
    });
    setRawComments((prev) => {
      const next = prev.filter((x) => x.id !== e.messageId);
      if (next.length < prev.length) setCommentTotal((c) => Math.max(0, c - 1));
      return next;
    });
  }, [entityType, entityId]));

  // ── Derived data ──────────────────────────────────────────────────────

  const chatMessages: ChatMessage[] = useMemo(
    () => rawChat.map(mapToChat),
    [rawChat],
  );

  const comments: Comment[] = useMemo(() => {
    const flat = rawComments.map(mapToComment);
    return buildCommentTree(flat);
  }, [rawComments]);

  // ── Mutations ─────────────────────────────────────────────────────────

  const sendMessage = useCallback(
    async (content: string) => {
      if (!entityId) return;
      const dto = await messageService.createMessage(entityType, entityId, {
        type: 'message',
        content,
      });
      setRawChat((prev) => {
        if (prev.some((x) => x.id === dto.id)) return prev;
        setChatTotal((c) => c + 1);
        return [...prev, dto];
      });
    },
    [entityType, entityId],
  );

  const addComment = useCallback(
    async (content: string, parentId?: UUID) => {
      if (!entityId) return;
      const dto = await messageService.createMessage(entityType, entityId, {
        type: 'comment',
        content,
        mentions: [],
        parentId,
      });
      setRawComments((prev) => {
        if (prev.some((x) => x.id === dto.id)) return prev;
        setCommentTotal((c) => c + 1);
        return [...prev, dto];
      });
    },
    [entityType, entityId],
  );

  const editComment = useCallback(
    async (messageId: UUID, content: string) => {
      if (!entityId) return;
      const updated = await messageService.updateMessage(entityType, entityId, messageId, {
        content,
        mentions: [],
      });
      setRawComments((prev) => prev.map((c) => (c.id === messageId ? updated : c)));
    },
    [entityType, entityId],
  );

  const deleteComment = useCallback(
    async (messageId: UUID) => {
      if (!entityId) return;
      await messageService.deleteMessage(entityType, entityId, messageId);
      setRawChat((prev) => {
        const next = prev.filter((c) => c.id !== messageId);
        if (next.length < prev.length) setChatTotal((c) => Math.max(0, c - 1));
        return next;
      });
      setRawComments((prev) => {
        const next = prev.filter((c) => c.id !== messageId);
        if (next.length < prev.length) setCommentTotal((c) => Math.max(0, c - 1));
        return next;
      });
    },
    [entityType, entityId],
  );

  // chatCount / commentCount = SERVER TOTALS (for tab badges showing real total)
  const chatCount    = chatTotalCount;
  const commentCount = commentTotalCount;

  return {
    chatMessages,
    comments,
    loading,
    error,
    chatCount,
    commentCount,
    hasMoreChat,
    hasMoreComments,
    reload,
    loadMoreChat,
    loadMoreComments,
    sendMessage,
    addComment,
    editComment,
    deleteComment,
  };
};
