import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { useResponsive } from '../../hooks/useResponsive';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import {
  fetchTasks,
  setFilters,
  setPage,
} from '../../store/slices/tasksSlice';
import {
  openSlideout,
  closeSlideout,
} from '../../store/slices/uiSlice';
import { Task, TaskFilters } from '../../models/Task';
import { Button } from '../../components/common/Button';
import { Slideout } from '../../components/common/Slideout';
import { TableCard } from '../../components/common/TableCard';
import { Pagination } from '../../components/common/Pagination';
import {
  TaskStatsCards,
  TaskFiltersComponent,
  TaskTable,
  KanbanBoard,
  CreateTaskForm,
} from './components';
import styles from './TasksListPage.module.css';

type ViewMode = 'list' | 'kanban';

const TasksListPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { isMobile } = useResponsive();
  const { items, loading, filters, pagination } = useAppSelector(
    (state) => state.tasks
  );
  const { slideouts } = useAppSelector((state) => state.ui);

  // Keep skeleton visible for at least 300 ms to avoid flash-of-loading.
  const showLoading = useMinLoadingTime(loading);

  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [isExpanded, setIsExpanded] = useState(false);

  // Fetch tasks on mount and when filters/page change
  useEffect(() => {
    dispatch(fetchTasks({ filters, page: pagination.page, pageSize: pagination.pageSize }));
  }, [dispatch, filters, pagination.page, pagination.pageSize]);

  // Handlers
  const handleFilterChange = (newFilters: TaskFilters) => {
    dispatch(setFilters(newFilters));
    dispatch(setPage(1)); // Reset to first page on filter change
  };

  const handleCreateClick = () => {
    dispatch(openSlideout('createTask'));
  };

  const handleTaskClick = (task: Task) => {
    navigate(`/tasks/${task.id}`);
  };

  const handleCreateSuccess = () => {
    dispatch(closeSlideout('createTask'));
    dispatch(fetchTasks({ filters, page: pagination.page, pageSize: pagination.pageSize }));
  };

  const handleUpdateSuccess = () => {
    dispatch(fetchTasks({ filters, page: pagination.page, pageSize: pagination.pageSize }));
  };

  const handlePageChange = (page: number) => {
    dispatch(setPage(page));
  };

  // Calculate stats from items
  const stats = {
    total: items.length,
    assigned: items.filter((t) => t.status === 'assigned').length,
    inProgress: items.filter((t) => t.status === 'in_progress').length,
    completed: items.filter((t) => t.status === 'completed').length,
    overdue: items.filter((t) => new Date(t.dueDate) < new Date() && t.status !== 'completed').length,
  };

  return (
    <>
      {/* Backdrop for expand mode */}
      {isExpanded && (
        <div 
          className={styles.backdrop} 
          onClick={() => setIsExpanded(false)} 
        />
      )}

      <div className={`${styles.tasksListPage} ${isExpanded ? styles.expanded : ''}`}>
        {/* Expand Button */}
        <button
          className={styles.expandButton}
          onClick={() => setIsExpanded(!isExpanded)}
          aria-label={isExpanded ? 'Thu gọn' : 'Mở rộng'}
        >
          <i className={`fas fa-${isExpanded ? 'compress' : 'expand'}`}></i>
          {isExpanded ? 'Thu gọn' : 'Mở rộng'}
        </button>

        {/* Page Header */}
        <div className={styles.header}>
          <div className={styles.headerLeft}>
            <h1 className={styles.pageTitle}>
              <i className="fas fa-tasks"></i> Công Việc Của Tôi
            </h1>
          </div>
          <div className={styles.headerRight}>
            <Button variant="primary" onClick={handleCreateClick}>
              <i className="fas fa-plus"></i>
              {!isMobile && ' Tạo Task Mới'}
            </Button>
          </div>
        </div>

        {/* Stats Cards */}
        <TaskStatsCards stats={stats} loading={showLoading} />

      {/* Filters & View Toggle */}
      <TableCard
        header={
          <div className ={styles.filterHeader}>
            <TaskFiltersComponent
              filters={filters}
              onFilterChange={handleFilterChange}
            />
            <div className={styles.viewToggle}>
              <button
                className={viewMode === 'list' ? styles.active : ''}
                onClick={() => setViewMode('list')}
              >
                <i className="fas fa-list"></i> List
              </button>
              <button
                className={viewMode === 'kanban' ? styles.active : ''}
                onClick={() => setViewMode('kanban')}
              >
                <i className="fas fa-columns"></i> Kanban
              </button>
            </div>
          </div>
        }
        footer={
          viewMode === 'list' && !showLoading && items.length > 0 ? (
            <Pagination
              currentPage={pagination.page}
              totalPages={Math.ceil(pagination.totalCount / pagination.pageSize)}
              totalCount={pagination.totalCount}
              pageSize={pagination.pageSize}
              onPageChange={handlePageChange}
            />
          ) : undefined
        }
      >
        {/* Content */}
        {viewMode === 'list' ? (
          <TaskTable
            tasks={items}
            loading={showLoading}
            onTaskClick={handleTaskClick}
          />
        ) : (
          <KanbanBoard
            tasks={items}
            loading={showLoading}
            onTaskClick={handleTaskClick}
            onUpdateSuccess={handleUpdateSuccess}
          />
        )}
      </TableCard>
      {/* Create Task Slideout */}
      <Slideout
        isOpen={slideouts.createTask || false}
        onClose={() => dispatch(closeSlideout('createTask'))}
        title="Tạo Task Mới"
      >
        <CreateTaskForm onSuccess={handleCreateSuccess} />
      </Slideout>
    </div>
    </>
  );
};

export default TasksListPage;
