import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { fetchTicketById } from '../../store/slices/ticketsSlice';
import { addToast, openSlideout, closeSlideout, resetEditTicketForm } from '../../store/slices/uiSlice';
import { useResponsive } from '../../hooks/useResponsive';
import { UUID } from '../../models/common';
import { Button } from '../../components/common/Button';
import { Card } from '../../components/common/Card';
import { Slideout } from '../../components/common/Slideout';
import { TicketActions } from '../../components/tickets/TicketActions';
import { EditTicketForm } from '../../components/tickets/EditTicketForm';
import { AssignTicketModal } from '../../components/tickets/AssignTicketModal';
import { TriageTicketModal } from '../../components/tickets/TriageTicketModal';
import { ResolveTicketModal } from '../../components/tickets/ResolveTicketModal/ResolveTicketModal';
import { CloseTicketModal } from '../../components/tickets/CloseTicketModal/CloseTicketModal';
import { ReopenTicketModal } from '../../components/tickets/ReopenTicketModal/ReopenTicketModal';
import { RequestHelpModal } from '../../components/tickets/RequestHelpModal/RequestHelpModal';
import SupportAssignmentModal from '../../components/tickets/SupportAssignmentModal/SupportAssignmentModal';
import TicketHeader from './components/TicketHeader';
import TicketInfo from './components/TicketInfo';
import TicketTabs from './components/TicketTabs';
import TicketSidebar from './components/TicketSidebar';
import styles from './TicketDetailPage.module.css';

const TicketDetailPage: React.FC = () => {
  const { id } = useParams<{ id: UUID }>();
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { isMobile } = useResponsive();
  
  const ticket = useAppSelector((state) => state.tickets.selectedTicket);
  const loading = useAppSelector((state) => state.tickets.loading);
  const { slideouts } = useAppSelector((state) => state.ui);
  const [assignModalOpen, setAssignModalOpen]   = useState(false);
  const [triageModalOpen, setTriageModalOpen]   = useState(false);
  const [resolveModalOpen, setResolveModalOpen] = useState(false);
  const [closeModalOpen, setCloseModalOpen]     = useState(false);
  const [reopenModalOpen, setReopenModalOpen]   = useState(false);
  const [helpModalOpen, setHelpModalOpen]       = useState(false);
  const [supportModalOpen, setSupportModalOpen] = useState(false);

  const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

  useEffect(() => {
    const loadTicket = async () => {
      if (!id || !UUID_REGEX.test(id)) {
        navigate('/tickets');
        return;
      }

      try {
        await dispatch(fetchTicketById(id)).unwrap();
      } catch (error) {
        dispatch(
          addToast({
            message: 'Không thể tải thông tin phiếu',
            type: 'error',
          })
        );
        navigate('/tickets');
      }
    };

    loadTicket();
  }, [dispatch, id, navigate]);

  const handleBack = () => {
    navigate('/tickets');
  };

  const handleView = () => {
    // Already on detail page, do nothing
  };

  const handleEdit = () => {
    dispatch(openSlideout('editTicket'));
  };

  const handleAssign = () => {
    setAssignModalOpen(true);
  };

  const handleTriage = () => {
    setTriageModalOpen(true);
  };

  const handleResolve = () => {
    setResolveModalOpen(true);
  };

  const handleClose = () => {
    setCloseModalOpen(true);
  };

  const handleRequestHelp = () => {
    setHelpModalOpen(true);
  };

  const handleAssignHelper = () => {
    setSupportModalOpen(true);
  };

  const handleReopen = () => {
    setReopenModalOpen(true);
  };

  const handleAssignSuccess = () => {
    setAssignModalOpen(false);
    // Reload ticket data after assignment
    if (id) {
      dispatch(fetchTicketById(id));
    }
  };

  const handleTriageSuccess = () => {
    setTriageModalOpen(false);
    // Reload ticket data after triage
    if (id) {
      dispatch(fetchTicketById(id));
    }
  };

  const reloadTicket = () => {
    if (id) dispatch(fetchTicketById(id));
  };

  const handleEditSuccess = () => {
    dispatch(closeSlideout('editTicket'));
    dispatch(resetEditTicketForm());
    // Reload ticket data after edit
    if (id) {
      dispatch(fetchTicketById(id));
    }
  };

  if (loading || !ticket) {
    return (
      <div className={styles.loading}>
        <i className="fas fa-spinner fa-spin"></i>
        <span>Đang tải...</span>
      </div>
    );
  }

  return (
    <div className={styles.container}>
      {/* Page Header with Back Button */}
      <div className={styles.pageHeader}>
        <div className={styles.pageHeaderLeft}>
          <Button variant="secondary" onClick={handleBack}>
            <i className="fas fa-arrow-left"></i> Quay lại
          </Button>
          <TicketHeader ticket={ticket} />
        </div>
        <div className={styles.pageHeaderActions}>
          <TicketActions
            ticket={ticket}
            variant="detail"
            size="md"
            showLabels={true}
            onView={() => handleView()}
            onEdit={handleEdit}
            onAssign={handleAssign}
            onTriage={handleTriage}
            onResolve={handleResolve}
            onClose={handleClose}
            onRequestHelp={handleRequestHelp}
            onAssignHelper={handleAssignHelper}
            onReopen={handleReopen}
          />
        </div>
      </div>

      {/* Main Content Grid */}
      <div className={styles.contentGrid}>
        {/* Main Column */}
        <div className={styles.mainColumn}>
          {/* Ticket Info Card */}
          <Card>
            <div className={styles.cardHeader}>
              <h3 className={styles.cardTitle}>
                <i className="fas fa-info-circle"></i>
                Thông Tin Ticket
              </h3>
            </div>
            <div className={styles.cardBody}>
              <TicketInfo ticket={ticket} />
            </div>
          </Card>

          {/* Tabs Section */}
          <TicketTabs ticket={ticket} />
        </div>

        {/* Right Sidebar */}
        <TicketSidebar ticket={ticket} />
      </div>

      {/* Edit Slideout */}
      <Slideout
        isOpen={slideouts.editTicket}
        onClose={() => {
          dispatch(closeSlideout('editTicket'));
          dispatch(resetEditTicketForm());
        }}
        title="Chỉnh Sửa Ticket"
        width={isMobile ? '100%' : '600px'}
      >
        {id && (
          <EditTicketForm
            ticketId={id}
            onSuccess={handleEditSuccess}
            onCancel={() => {
              dispatch(closeSlideout('editTicket'));
              dispatch(resetEditTicketForm());
            }}
          />
        )}
      </Slideout>

      {/* Assign Modal */}
      {ticket && (
        <AssignTicketModal
          isOpen={assignModalOpen}
          ticketId={ticket.id}
          ticketTitle={ticket.title}
          onClose={() => setAssignModalOpen(false)}
          onSuccess={handleAssignSuccess}
        />
      )}

      {/* Triage Modal */}
      {ticket && (
        <TriageTicketModal
          isOpen={triageModalOpen}
          ticketId={ticket.id}
          onClose={() => setTriageModalOpen(false)}
          onSuccess={handleTriageSuccess}
        />
      )}

      {/* Resolve Modal */}
      {ticket && (
        <ResolveTicketModal
          isOpen={resolveModalOpen}
          ticketId={ticket.id}
          onClose={() => setResolveModalOpen(false)}
          onSuccess={() => { setResolveModalOpen(false); reloadTicket(); }}
        />
      )}

      {/* Close Modal */}
      {ticket && (
        <CloseTicketModal
          isOpen={closeModalOpen}
          ticketId={ticket.id}
          onClose={() => setCloseModalOpen(false)}
          onSuccess={() => { setCloseModalOpen(false); reloadTicket(); }}
        />
      )}

      {/* Reopen Modal */}
      {ticket && (
        <ReopenTicketModal
          isOpen={reopenModalOpen}
          ticketId={ticket.id}
          onClose={() => setReopenModalOpen(false)}
          onSuccess={() => { setReopenModalOpen(false); reloadTicket(); }}
        />
      )}

      {/* Request Help Modal */}
      {ticket && (
        <RequestHelpModal
          isOpen={helpModalOpen}
          ticketId={ticket.id}
          onClose={() => setHelpModalOpen(false)}
          onSuccess={() => { setHelpModalOpen(false); reloadTicket(); }}
        />
      )}

      {/* Support Assignment Modal */}
      {ticket && (
        <SupportAssignmentModal
          ticket={ticket}
          isOpen={supportModalOpen}
          onClose={() => setSupportModalOpen(false)}
          onSubmit={async (helpers) => {
            const { assignTicketSupport } = await import('../../store/slices/ticketsSlice');
            await dispatch(assignTicketSupport({
              ticketId: ticket.id,
              helpers: helpers.map((h) => ({ userId: h.userId, userName: h.userName })),
            })).unwrap();
            setSupportModalOpen(false);
            reloadTicket();
          }}
        />
      )}
    </div>
  );
};

export default TicketDetailPage;
