export const fetchAllManagerDashboardData = createAsyncThunk(
  'managerDashboard/fetchAll',
  async (_, { dispatch }) => {
    // Fetch all dashboard data in parallel
    await Promise.all([
      dispatch(fetchManagerStats()),
      dispatch(fetchTeamWorkload()),
      dispatch(fetchSLABreachAlerts()),
      dispatch(fetchPendingApprovals()),
      dispatch(fetchPerformanceData()),
    ]);
  }
);

