// Slice
const managerDashboardSlice = createSlice({
  name: 'managerDashboard',
  initialState,
  reducers: {
    clearManagerDashboard: (state) => {
      state.stats = null;
      state.teamWorkload = [];
      state.slaBreachAlerts = [];
      state.pendingApprovals = [];
      state.performanceTrend = [];
      state.priorityDistribution = null;
      state.error = null;
    },
    updateManagerStats: (
      state,
      action: PayloadAction<Partial<ManagerDashboardStats>>
    ) => {
      if (state.stats) {
        state.stats = { ...state.stats, ...action.payload };
      }
    },
    addSLAAlert: (state, action: PayloadAction<SLABreachAlert>) => {
      state.slaBreachAlerts.unshift(action.payload);
    },
  },
  extraReducers: (builder) => {
    // Fetch Manager Stats
    builder
      .addCase(fetchManagerStats.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchManagerStats.fulfilled, (state, action) => {
        state.loading = false;
        state.stats = action.payload;
      })
      .addCase(fetchManagerStats.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch manager stats';
      });

    // Fetch Team Workload
    builder
      .addCase(fetchTeamWorkload.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchTeamWorkload.fulfilled, (state, action) => {
        state.loading = false;
        state.teamWorkload = action.payload;
      })
      .addCase(fetchTeamWorkload.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch team workload';
      });

    // Fetch SLA Breach Alerts
    builder
      .addCase(fetchSLABreachAlerts.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchSLABreachAlerts.fulfilled, (state, action) => {
        state.loading = false;
        state.slaBreachAlerts = action.payload;
      })
      .addCase(fetchSLABreachAlerts.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch SLA alerts';
      });

    // Fetch Pending Approvals
    builder
      .addCase(fetchPendingApprovals.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchPendingApprovals.fulfilled, (state, action) => {
        state.loading = false;
        state.pendingApprovals = action.payload;
      })
      .addCase(fetchPendingApprovals.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch pending approvals';
      });

    // Fetch Performance Data
    builder
      .addCase(fetchPerformanceData.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchPerformanceData.fulfilled, (state, action) => {
        state.loading = false;
        state.performanceTrend = action.payload.trend;
        state.priorityDistribution = action.payload.distribution;
      })
      .addCase(fetchPerformanceData.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch performance data';
      });

    // Reassign SLA Alert
    builder
      .addCase(reassignSLAAlert.fulfilled, (state, action) => {
        // Remove the reassigned alert from the list
        state.slaBreachAlerts = state.slaBreachAlerts.filter(
          (alert) => alert.id !== action.payload.alertId
        );
      })
      .addCase(reassignSLAAlert.rejected, (state, action) => {
        state.error = action.error.message || 'Failed to reassign alert';
      });

    // Approve Task
    builder
      .addCase(approveTask.fulfilled, (state, action) => {
        // Remove the approved task from the list
        state.pendingApprovals = state.pendingApprovals.filter(
          (approval) => approval.id !== action.payload.approvalId
        );
      })
      .addCase(approveTask.rejected, (state, action) => {
        state.error = action.error.message || 'Failed to approve task';
      });

    // Reject Task
    builder
      .addCase(rejectTask.fulfilled, (state, action) => {
        // Remove the rejected task from the list
        state.pendingApprovals = state.pendingApprovals.filter(
          (approval) => approval.id !== action.payload.approvalId
        );
      })
      .addCase(rejectTask.rejected, (state, action) => {
        state.error = action.error.message || 'Failed to reject task';
      });
  },
});

export const { clearManagerDashboard, updateManagerStats, addSLAAlert } =
  managerDashboardSlice.actions;

export default managerDashboardSlice.reducer;
