/**
 * SecurityTab Component
 * Security settings and password change
 */

import React, { useState } from 'react';
import { UserSettings, ChangePasswordRequest, validatePassword } from '../../../models/Settings';
import { settingsService } from '../../../services/settingsService';
import styles from './SecurityTab.module.css';

interface SecurityTabProps {
  settings: UserSettings;
  onSave: (settings: Partial<UserSettings>) => void;
  saving: boolean;
}

export const SecurityTab: React.FC<SecurityTabProps> = ({ settings, onSave, saving }) => {
  const [security, setSecurity] = useState(settings.security);
  const [passwordForm, setPasswordForm] = useState<ChangePasswordRequest>({
    currentPassword: '',
    newPassword: '',
    confirmPassword: '',
  });
  const [changingPassword, setChangingPassword] = useState(false);
  const [passwordErrors, setPasswordErrors] = useState<string[]>([]);
  const [passwordSuccess, setPasswordSuccess] = useState(false);

  const handleSecurityChange = (field: string, value: any) => {
    setSecurity((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const handlePasswordChange = (field: keyof ChangePasswordRequest, value: string) => {
    setPasswordForm((prev) => ({
      ...prev,
      [field]: value,
    }));
    setPasswordErrors([]);
  };

  const handlePasswordSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validate passwords (no SystemSecuritySettings available here; use built-in defaults)
    const validation = validatePassword(passwordForm.newPassword);
    if (!validation.valid) {
      setPasswordErrors(validation.errors);
      return;
    }

    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      setPasswordErrors(['Mật khẩu xác nhận không khớp']);
      return;
    }

    try {
      setChangingPassword(true);
      setPasswordErrors([]);
      await settingsService.changePassword(passwordForm);
      setPasswordSuccess(true);
      setPasswordForm({
        currentPassword: '',
        newPassword: '',
        confirmPassword: '',
      });
      
      // Clear success message after 5 seconds
      setTimeout(() => setPasswordSuccess(false), 5000);
    } catch (err: any) {
      setPasswordErrors([err.message || 'Không thể đổi mật khẩu']);
    } finally {
      setChangingPassword(false);
    }
  };

  const handleSave = () => {
    onSave({ security });
  };

  const daysSincePasswordChange = settings.security.lastPasswordChange
    ? Math.floor(
        (Date.now() - new Date(settings.security.lastPasswordChange).getTime()) / (1000 * 60 * 60 * 24)
      )
    : null;

  return (
    <div className={styles.securityTab}>
      {/* Change Password */}
      <div className={styles.card}>
        <div className={styles.cardHeader}>
          <h3 className={styles.cardTitle}>Đổi mật khẩu</h3>
          <p className={styles.cardDescription}>
            Đảm bảo tài khoản của bạn sử dụng mật khẩu mạnh và an toàn
          </p>
        </div>

        <div className={styles.cardBody}>
          {passwordSuccess && (
            <div className={styles.successAlert}>
              <i className="fas fa-check-circle"></i>
              <span>Đổi mật khẩu thành công!</span>
            </div>
          )}

          {passwordErrors.length > 0 && (
            <div className={styles.errorAlert}>
              <i className="fas fa-exclamation-circle"></i>
              <div>
                {passwordErrors.map((error, index) => (
                  <div key={index}>{error}</div>
                ))}
              </div>
            </div>
          )}

          <form onSubmit={handlePasswordSubmit}>
            <div className={styles.formGroup}>
              <label className={styles.label}>Mật khẩu hiện tại</label>
              <input
                type="password"
                className={styles.input}
                value={passwordForm.currentPassword}
                onChange={(e) => handlePasswordChange('currentPassword', e.target.value)}
                required
              />
            </div>

            <div className={styles.formGroup}>
              <label className={styles.label}>Mật khẩu mới</label>
              <input
                type="password"
                className={styles.input}
                value={passwordForm.newPassword}
                onChange={(e) => handlePasswordChange('newPassword', e.target.value)}
                required
              />
            </div>

            <div className={styles.formGroup}>
              <label className={styles.label}>Xác nhận mật khẩu mới</label>
              <input
                type="password"
                className={styles.input}
                value={passwordForm.confirmPassword}
                onChange={(e) => handlePasswordChange('confirmPassword', e.target.value)}
                required
              />
            </div>

            <div className={styles.passwordRequirements}>
              <div className={styles.requirementTitle}>Yêu cầu mật khẩu:</div>
              <ul className={styles.requirementList}>
                <li>Ít nhất 8 ký tự</li>
                <li>Có ít nhất 1 chữ hoa</li>
                <li>Có ít nhất 1 chữ thường</li>
                <li>Có ít nhất 1 số</li>
                <li>Có ít nhất 1 ký tự đặc biệt</li>
              </ul>
            </div>

            <button
              type="submit"
              className={styles.changePasswordButton}
              disabled={changingPassword}
            >
              {changingPassword ? (
                <>
                  <i className="fas fa-spinner fa-spin"></i> Đang đổi mật khẩu...
                </>
              ) : (
                <>
                  <i className="fas fa-key"></i> Đổi mật khẩu
                </>
              )}
            </button>
          </form>

          {daysSincePasswordChange !== null && (
            <div className={styles.lastChange}>
              <i className="fas fa-info-circle"></i>
              Lần đổi mật khẩu gần nhất: {daysSincePasswordChange} ngày trước
            </div>
          )}
        </div>
      </div>

      {/* Security Settings */}
      <div className={styles.card}>
        <div className={styles.cardHeader}>
          <h3 className={styles.cardTitle}>Cài đặt Bảo mật</h3>
          <p className={styles.cardDescription}>
            Quản lý các tùy chọn bảo mật cho tài khoản của bạn
          </p>
        </div>

        <div className={styles.cardBody}>
          <div className={styles.formGroup}>
            <label className={styles.checkboxLabel}>
              <input
                type="checkbox"
                checked={security.twoFactorEnabled}
                onChange={(e) => handleSecurityChange('twoFactorEnabled', e.target.checked)}
              />
              <div>
                <span className={styles.checkboxTitle}>Xác thực hai yếu tố (2FA)</span>
                <span className={styles.checkboxDescription}>
                  Thêm lớp bảo mật bổ sung bằng mã xác thực qua ứng dụng
                </span>
              </div>
            </label>
          </div>

          <div className={styles.formGroup}>
            <label className={styles.label}>Thời gian chờ phiên làm việc (phút)</label>
            <select
              className={styles.select}
              value={security.sessionTimeout}
              onChange={(e) => handleSecurityChange('sessionTimeout', parseInt(e.target.value))}
            >
              <option value="15">15 phút</option>
              <option value="30">30 phút</option>
              <option value="60">60 phút</option>
              <option value="120">120 phút</option>
            </select>
            <span className={styles.helpText}>
              Tự động đăng xuất sau khoảng thời gian không hoạt động
            </span>
          </div>
        </div>

        <div className={styles.cardFooter}>
          <button
            onClick={handleSave}
            className={styles.saveButton}
            disabled={saving}
          >
            {saving ? (
              <>
                <i className="fas fa-spinner fa-spin"></i> Đang lưu...
              </>
            ) : (
              <>
                <i className="fas fa-save"></i> Lưu thay đổi
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};
