/**
 * Pure mapping: BFF aggregate DTOs → ReportsData model.
 *
 * Aggregates data from:
 *   - BffTicketPagedForReport   (GET /tickets)
 *   - BffTaskPagedForReport     (GET /tasks)
 *   - BffSlaStatsForReport      (GET /sla/stats)
 *   - BffSlaAlertsResponseForReport (GET /sla/alerts)
 */

import type {
  ReportsData,
  TicketPerformanceMetrics,
  TaskCompletionMetrics,
  TeamPerformanceMember,
  SLAComplianceMetrics,
  WorkloadMetrics,
  QualityMetrics,
  SLABreach,
  DataPoint,
  WorkloadItem,
} from '../../models/Report';
import type {
  BffTicketPagedForReport,
  BffTaskPagedForReport,
  BffSlaStatsForReport,
  BffSlaAlertsResponseForReport,
} from './responseModel';

// Ticket statuses considered "done"
const RESOLVED_STATUSES = new Set(['resolved', 'closed']);

// Ticket statuses considered "active / in backlog"
const ACTIVE_TICKET_STATUSES = new Set([
  'submitted', 'pending', 'triaged', 'assigned',
  'inprogress', 'helprequested', 'supportassigned', 'reopened',
]);

// Task statuses considered "active / in progress"
const ACTIVE_TASK_STATUSES_EXCLUDE = new Set(['completed', 'cancelled']);

/** Build initials from a full name string. */
function initials(name: string): string {
  return name
    .split(' ')
    .map((w) => w[0] ?? '')
    .join('')
    .substring(0, 2)
    .toUpperCase();
}

/** Compute weekly counts for the past N weeks (oldest → newest). */
function weeklyTrend(
  dates: string[],
  weeksBack = 4,
  label = (i: number) => `Tuần ${i + 1}`,
): DataPoint[] {
  const now = new Date();
  return Array.from({ length: weeksBack }, (_, i) => {
    const weekEnd = new Date(now);
    weekEnd.setDate(now.getDate() - (weeksBack - 1 - i) * 7);
    const weekStart = new Date(weekEnd);
    weekStart.setDate(weekEnd.getDate() - 7);
    const count = dates.filter((d) => {
      const t = new Date(d);
      return t >= weekStart && t < weekEnd;
    }).length;
    return { label: label(i), value: count };
  });
}

// ─────────────────────────────────────────────────────────────────────────────

export function mapBffToReportsData(
  tickets: BffTicketPagedForReport,
  tasks: BffTaskPagedForReport,
  slaStats: BffSlaStatsForReport,
  slaAlerts: BffSlaAlertsResponseForReport,
): ReportsData {
  const now = new Date();

  // ── Ticket Performance ──────────────────────────────────────────────────────
  const resolvedTickets = tickets.items.filter((t) =>
    RESOLVED_STATUSES.has(t.status.toLowerCase()),
  ).length;
  const totalTickets = tickets.totalCount;
  const completionRate =
    totalTickets > 0
      ? Math.round((resolvedTickets / totalTickets) * 1000) / 10  // 1 dp
      : 0;

  const ticketCreatedDates = tickets.items.map((t) => t.createdAt);
  const ticketTrend = weeklyTrend(ticketCreatedDates);

  const ticketPerformance: TicketPerformanceMetrics = {
    totalTickets,
    resolvedTickets,
    averageTimeHours: 0,   // Not available from TicketListItemDto
    completionRate,
    trend: ticketTrend,
  };

  // ── Task Completion ─────────────────────────────────────────────────────────
  const completedTasks = tasks.items.filter(
    (t) => t.status.toLowerCase() === 'completed',
  ).length;
  const totalTasks = tasks.totalCount;
  const overdueTasksLocal = tasks.items.filter(
    (t) =>
      t.dueDate &&
      new Date(t.dueDate) < now &&
      !ACTIVE_TASK_STATUSES_EXCLUDE.has(t.status.toLowerCase()),
  ).length;
  // Prefer BFF aggregate for overdue count (more accurate, includes all records)
  const overdueTasks =
    slaStats.overdueTasks > 0 ? slaStats.overdueTasks : overdueTasksLocal;
  const onTimeRate =
    completedTasks > 0
      ? Math.max(
          0,
          Math.round(
            ((completedTasks - Math.min(overdueTasks, completedTasks)) /
              completedTasks) *
              100,
          ),
        )
      : 0;

  const completedTaskDates = tasks.items
    .filter((t) => t.status.toLowerCase() === 'completed')
    .map((t) => t.updatedAt);
  const taskTrend = weeklyTrend(completedTaskDates);

  const taskCompletion: TaskCompletionMetrics = {
    totalTasks,
    completedTasks,
    overdueTasks,
    onTimeRate,
    trend: taskTrend,
  };

  // ── Team Performance ────────────────────────────────────────────────────────
  // Group resolved tickets by assignee
  const ticketsByAssignee = new Map<string, { name: string; count: number }>();
  for (const t of tickets.items.filter(
    (t) => RESOLVED_STATUSES.has(t.status.toLowerCase()) && t.assigneeId,
  )) {
    const key = t.assigneeId!;
    const existing = ticketsByAssignee.get(key);
    if (existing) existing.count++;
    else ticketsByAssignee.set(key, { name: t.assigneeName ?? key, count: 1 });
  }

  // Group completed tasks by assignee
  const tasksByAssignee = new Map<string, { name: string; count: number }>();
  for (const t of tasks.items.filter(
    (t) => t.status.toLowerCase() === 'completed' && t.assigneeId,
  )) {
    const key = t.assigneeId!;
    const existing = tasksByAssignee.get(key);
    if (existing) existing.count++;
    else tasksByAssignee.set(key, { name: t.assigneeName ?? key, count: 1 });
  }

  const allAssigneeIds = new Set([
    ...ticketsByAssignee.keys(),
    ...tasksByAssignee.keys(),
  ]);

  const teamPerformance: TeamPerformanceMember[] = Array.from(allAssigneeIds)
    .map((id) => {
      const td = ticketsByAssignee.get(id);
      const sk = tasksByAssignee.get(id);
      const name = td?.name ?? sk?.name ?? id;
      return {
        id,
        name,
        avatar: initials(name),
        ticketsResolved: td?.count ?? 0,
        tasksCompleted: sk?.count ?? 0,
        averageTime: 0,   // Not available from list endpoints
      };
    })
    .sort(
      (a, b) =>
        b.ticketsResolved +
        b.tasksCompleted -
        (a.ticketsResolved + a.tasksCompleted),
    )
    .slice(0, 10);

  // ── SLA Compliance ──────────────────────────────────────────────────────────
  // overallCompliance = 100 − ticketSlaBreachRate (which is already a %)
  const overallCompliance = Math.max(
    0,
    Math.round(100 - slaStats.ticketSlaBreachRate),
  );

  // Per-priority compliance from ticket list
  type PrioAccum = { breached: number; total: number };
  const byPrioMap: Record<string, PrioAccum> = {
    critical: { breached: 0, total: 0 },
    high:     { breached: 0, total: 0 },
    medium:   { breached: 0, total: 0 },
    low:      { breached: 0, total: 0 },
  };
  for (const t of tickets.items) {
    const p = t.priority.toLowerCase();
    if (byPrioMap[p]) {
      byPrioMap[p].total++;
      if (t.slaBreached) byPrioMap[p].breached++;
    }
  }
  const toCompliance = (acc: PrioAccum) =>
    acc.total > 0
      ? Math.round((1 - acc.breached / acc.total) * 100)
      : 100;

  // Map priority → SLA target hours (standard hospital SLA tiers)
  const SLA_TARGET_HOURS: Record<string, string> = {
    critical: '2h',
    high:     '4h',
    medium:   '24h',
    low:      '72h',
  };

  // SLA breach detail rows — overdue ticket-domain alerts only
  const breaches: SLABreach[] = slaAlerts.items
    .filter((a) => a.isOverdue && a.domain === 'ticket')
    .slice(0, 20)
    .map((a) => {
      const prio = a.priority.toLowerCase();
      const overdueHours = Math.round(Math.abs(a.hoursRemaining));
      return {
        ticketId:  a.entityNumber,
        title:     a.entityTitle,
        priority:  prio as SLABreach['priority'],
        assignee:  a.assigneeName ?? 'Chưa phân công',
        slaTarget: SLA_TARGET_HOURS[prio] ?? '24h',
        actualTime: `${overdueHours}h`,
        breachTime: `+${overdueHours}h`,
        status:    a.status,
      };
    });

  const slaCompliance: SLAComplianceMetrics = {
    overallCompliance,
    trend: [],   // No historical trend available from current API
    byPriority: {
      critical: toCompliance(byPrioMap.critical),
      high:     toCompliance(byPrioMap.high),
      medium:   toCompliance(byPrioMap.medium),
      low:      toCompliance(byPrioMap.low),
    },
    breaches,
  };

  // ── Workload ────────────────────────────────────────────────────────────────
  // Active tasks per assignee
  const activeByAssignee = new Map<string, { name: string; count: number }>();
  for (const t of tasks.items.filter(
    (t) =>
      !ACTIVE_TASK_STATUSES_EXCLUDE.has(t.status.toLowerCase()) && t.assigneeId,
  )) {
    const key = t.assigneeId!;
    const existing = activeByAssignee.get(key);
    if (existing) existing.count++;
    else activeByAssignee.set(key, { name: t.assigneeName ?? key, count: 1 });
  }

  const workloadItems: WorkloadItem[] = Array.from(activeByAssignee.entries())
    .map(([userId, data]) => ({
      userId,
      userName: data.name,
      avatar: initials(data.name),
      activeTasksCount: data.count,
    }))
    .sort((a, b) => b.activeTasksCount - a.activeTasksCount)
    .slice(0, 10);

  const activeTaskCount = tasks.items.filter(
    (t) => !ACTIVE_TASK_STATUSES_EXCLUDE.has(t.status.toLowerCase()),
  ).length;
  const utilized =
    tasks.totalCount > 0
      ? Math.round((activeTaskCount / tasks.totalCount) * 100)
      : 0;

  const backlogTickets = tickets.items.filter((t) =>
    ACTIVE_TICKET_STATUSES.has(t.status.toLowerCase()),
  );
  const backlogCounts = backlogTickets.reduce(
    (acc, t) => {
      const p = t.priority.toLowerCase();
      acc.total++;
      if (p === 'critical') acc.critical++;
      else if (p === 'high') acc.high++;
      else acc.medium++;
      return acc;
    },
    { total: 0, critical: 0, high: 0, medium: 0 },
  );

  const workload: WorkloadMetrics = {
    currentWorkload: workloadItems,
    capacityUtilization: { utilized, available: 100 - utilized },
    backlog: backlogCounts,
  };

  // ── Quality ─────────────────────────────────────────────────────────────────
  // No rating data available from list endpoints — return neutral defaults.
  const quality: QualityMetrics = {
    userSatisfaction: {
      averageRating: 0,
      totalRatings: 0,
      distribution: [0, 0, 0, 0, 0],
    },
    firstTimeFixRate: {
      fixedFirstTime: 0,
      reopenRate: 0,
      trend: [],
    },
  };

  return {
    ticketPerformance,
    taskCompletion,
    teamPerformance,
    slaCompliance,
    workload,
    quality,
  };
}
