import React, { useState, useMemo } from 'react';
import { Task } from '../../../models/Task';
import { Card, Tabs, Tab } from '../../../components/common';
import { ChatTab, ChatMessage, CommentsTab, Comment, ActivityTab, ActivityType, AttachmentsTab } from '../../../components/shared';
import type { Activity } from '../../../components/shared';
import { ChecklistTab } from './ChecklistTab';
import { SubtaskState } from '../types';
import { TabType } from '../utils';
import styles from './TaskTabs.module.css';

interface TaskTabsProps {
  task: Task;
  /** Current authenticated user id (for own-message alignment) */
  currentUserId?: string;
  // Chat / Comments data (from useTaskComments)
  chatMessages: ChatMessage[];
  comments: Comment[];
  onSendMessage: (message: string) => Promise<void>;
  onAddComment: (content: string, parentId?: string) => Promise<void>;
  onEditComment: (commentId: string, content: string) => Promise<void>;
  onDeleteComment: (commentId: string) => Promise<void>;
  // Pagination props
  chatCount: number;
  commentCount: number;
  hasMoreChat: boolean;
  onLoadMoreChat: () => Promise<void>;
  hasMoreComments: boolean;
  onLoadMoreComments: () => Promise<void>;
  loading: boolean;
  // Checklist props
  editingSubtasks: Map<string, SubtaskState>;
  newSubtaskTitle: string;
  onToggleSubtask: (subtaskId: string) => Promise<void>;
  onAddSubtask: () => Promise<void>;
  onDeleteSubtask: (subtaskId: string) => Promise<void>;
  onStartEdit: (subtaskId: string, currentTitle: string) => void;
  onCancelEdit: (subtaskId: string) => void;
  onSaveEdit: (subtaskId: string) => Promise<void>;
  onEditTitleChange: (subtaskId: string, value: string) => void;
  onNewSubtaskChange: (value: string) => void;
  isProcessing: boolean;
}

const TaskTabs: React.FC<TaskTabsProps> = ({
  task,
  currentUserId,
  chatMessages,
  comments,
  onSendMessage,
  onAddComment,
  onEditComment,
  onDeleteComment,
  chatCount,
  commentCount,
  hasMoreChat,
  onLoadMoreChat,
  hasMoreComments,
  onLoadMoreComments,
  loading,
  editingSubtasks,
  newSubtaskTitle,
  onToggleSubtask,
  onAddSubtask,
  onDeleteSubtask,
  onStartEdit,
  onCancelEdit,
  onSaveEdit,
  onEditTitleChange,
  onNewSubtaskChange,
  isProcessing,
}) => {
  const [activeTab, setActiveTab] = useState<TabType>('checklist');

  // Define tabs configuration with overflow detection support
  const tabs: Tab[] = useMemo(
    () => [
      {
        id: 'checklist',
        label: 'Checklist',
        icon: 'fas fa-tasks',
        badge: task.subtasks?.filter((st) => !st.completed).length || 0,
        badgeColor: 'primary' as const,
      },
      {
        id: 'chat',
        label: 'Trao đổi',
        icon: 'fas fa-comments',
        badge: chatCount,
        badgeColor: 'primary' as const,
      },
      {
        id: 'comments',
        label: 'Bình luận',
        icon: 'fas fa-comment-dots',
        badge: commentCount,
        badgeColor: 'gray' as const,
      },
      {
        id: 'attachments',
        label: 'Files',
        icon: 'fas fa-paperclip',
        badge: 0,
        badgeColor: 'gray' as const,
      },
      {
        id: 'activity',
        label: 'Activity',
        icon: 'fas fa-history',
      },
    ],
    [task.subtasks, chatCount, commentCount]
  );

  const renderTabContent = () => {
    switch (activeTab) {
      case 'checklist':
        return (
          <ChecklistTab
            task={task}
            editingSubtasks={editingSubtasks}
            newSubtaskTitle={newSubtaskTitle}
            onToggleSubtask={onToggleSubtask}
            onAddSubtask={onAddSubtask}
            onDeleteSubtask={onDeleteSubtask}
            onStartEdit={onStartEdit}
            onCancelEdit={onCancelEdit}
            onSaveEdit={onSaveEdit}
            onEditTitleChange={onEditTitleChange}
            onNewSubtaskChange={onNewSubtaskChange}
            isProcessing={isProcessing}
          />
        );
      case 'chat':
        return (
          <ChatTab
            entityId={task.id}
            entityType="task"
            messages={chatMessages}
            currentUserId={currentUserId}
            onSendMessage={onSendMessage}
            hasMore={hasMoreChat}
            loading={loading}
            onLoadMore={onLoadMoreChat}
          />
        );
      case 'comments':
        return (
          <CommentsTab
            entityId={task.id}
            entityType="task"
            currentUserId={currentUserId}
            comments={comments}
            onAddComment={onAddComment}
            onEditComment={onEditComment}
            onDeleteComment={onDeleteComment}
            hasMore={hasMoreComments}
            loading={loading}
            onLoadMore={onLoadMoreComments}
          />
        );
      case 'activity': {
        const activities: Activity[] = (task.activities ?? []).map((a) => ({
          id:          a.id,
          entityId:    task.id,
          type:        a.type as ActivityType,
          actor:       a.actor,
          description: a.description,
          timestamp:   a.timestamp,
          metadata:    (a.fromStatus || a.toStatus)
            ? { fromStatus: a.fromStatus, toStatus: a.toStatus }
            : undefined,
        }));
        return (
          <ActivityTab
            entityId={task.id}
            entityType="task"
            activities={activities}
          />
        );
      }
      case 'attachments':
        return (
          <AttachmentsTab
            entityId={task.id}
            entityType="task"
            attachments={[]}
            onUpload={async (files) => {
              console.log('Upload task files:', files);
              // TODO: Call API to upload files
            }}
          />
        );
      default:
        return null;
    }
  };

  return (
    <Card>
      <div className={styles.tabsHeader}>
        <Tabs
          tabs={tabs}
          activeTab={activeTab}
          onTabChange={(tabId) => setActiveTab(tabId as TabType)}
          variant="underline"
        />
      </div>
      <div className={styles.tabContent}>{renderTabContent()}</div>
    </Card>
  );
};

export default TaskTabs;
