import React, { useState, useRef, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { RootState } from '../../../store/store';
import styles from './ReactionPicker.module.css';

export interface Reaction {
  emoji: string;
  label: string;
  count: number;
  users: string[]; // User IDs who reacted
  hasReacted?: boolean; // Current user has reacted
}

interface ReactionPickerProps {
  reactions?: Reaction[];
  onReact: (emoji: string) => void;
  onUnreact: (emoji: string) => void;
  className?: string;
}

const EMOJI_LIST = [
  { emoji: '👍', label: 'Thích' },
  { emoji: '❤️', label: 'Yêu thích' },
  { emoji: '😄', label: 'Vui' },
  { emoji: '😮', label: 'Wow' },
  { emoji: '😢', label: 'Buồn' },
  { emoji: '🙏', label: 'Cảm ơn' },
  { emoji: '🎉', label: 'Chúc mừng' },
  { emoji: '👏', label: 'Tuyệt vời' },
  { emoji: '🔥', label: 'Hot' },
  { emoji: '✅', label: 'Đồng ý' },
  { emoji: '💡', label: 'Ý tưởng' },
  { emoji: '🚀', label: 'Đẩy mạnh' },
];

export const ReactionPicker: React.FC<ReactionPickerProps> = ({
  reactions = [],
  onReact,
  onUnreact,
  className = '',
}) => {
  const [showPicker, setShowPicker] = useState(false);
  const [hoveredReaction, setHoveredReaction] = useState<Reaction | null>(null);
  const pickerRef = useRef<HTMLDivElement>(null);
  // const currentUser = useSelector((state: RootState) => state.users.currentUser);
  const users = useSelector((state: RootState) => state.users.users);

  const handleReactionClick = (reaction: Reaction) => {
    if (reaction.hasReacted) {
      onUnreact(reaction.emoji);
    } else {
      onReact(reaction.emoji);
    }
  };

  const handleEmojiSelect = (emoji: string) => {
    const existingReaction = reactions.find((r) => r.emoji === emoji);
    if (existingReaction?.hasReacted) {
      onUnreact(emoji);
    } else {
      onReact(emoji);
    }
    setShowPicker(false);
  };

  const getUserNames = (userIds: string[]) => {
    return userIds
      .map((id) => users.find((u) => u.id === id)?.fullName || 'Unknown')
      .join(', ');
  };

  // Close picker when clicking outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (pickerRef.current && !pickerRef.current.contains(e.target as Node)) {
        setShowPicker(false);
      }
    };

    if (showPicker) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [showPicker]);

  return (
    <div className={`${styles.reactionContainer} ${className}`}>
      {/* Existing reactions */}
      <div className={styles.reactions}>
        {reactions
          .filter((r) => r.count > 0)
          .map((reaction, index) => (
            <button
              key={index}
              className={`${styles.reaction} ${reaction.hasReacted ? styles.reacted : ''}`}
              onClick={() => handleReactionClick(reaction)}
              onMouseEnter={() => setHoveredReaction(reaction)}
              onMouseLeave={() => setHoveredReaction(null)}
              title={getUserNames(reaction.users)}
            >
              <span className={styles.emoji}>{reaction.emoji}</span>
              <span className={styles.count}>{reaction.count}</span>
            </button>
          ))}

        {/* Add reaction button */}
        <div className={styles.pickerWrapper} ref={pickerRef}>
          <button
            className={styles.addReaction}
            onClick={() => setShowPicker(!showPicker)}
            title="Thêm reaction"
          >
            <i className="fas fa-smile-plus"></i>
          </button>

          {/* Emoji picker dropdown */}
          {showPicker && (
            <div className={styles.picker}>
              <div className={styles.pickerHeader}>
                <i className="fas fa-smile"></i>
                <span>Chọn reaction</span>
              </div>
              <div className={styles.emojiGrid}>
                {EMOJI_LIST.map((item, index) => (
                  <button
                    key={index}
                    className={styles.emojiButton}
                    onClick={() => handleEmojiSelect(item.emoji)}
                    title={item.label}
                  >
                    {item.emoji}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Hover tooltip showing who reacted */}
      {hoveredReaction && hoveredReaction.users.length > 0 && (
        <div className={styles.tooltip}>
          <div className={styles.tooltipEmoji}>{hoveredReaction.emoji}</div>
          <div className={styles.tooltipUsers}>{getUserNames(hoveredReaction.users)}</div>
        </div>
      )}
    </div>
  );
};
