import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';
import { Ticket, TicketFilters } from '../../models/Ticket';
import { ticketService } from '../../services/ticketService';
import { UUID } from '../../models/common';

interface TicketsState {
  items: Ticket[];
  selectedTicket: Ticket | null;
  filters: TicketFilters;
  loading: boolean;
  error: string | null;
  stats: {
    total: number;
    submitted: number;
    inProgress: number;
    resolved: number;
    closed: number;
  };
  pagination: {
    page: number;
    pageSize: number;
    totalCount: number;
  };
}

const initialState: TicketsState = {
  items: [],
  selectedTicket: null,
  filters: {},
  loading: false,
  error: null,
  stats: {
    total: 0,
    submitted: 0,
    inProgress: 0,
    resolved: 0,
    closed: 0,
  },
  pagination: {
    page: 1,
    pageSize: 20,
    totalCount: 0,
  },
};

// Async thunks
export const fetchTickets = createAsyncThunk(
  'tickets/fetchTickets',
  async (filters: TicketFilters = {}) => {
    const response = await ticketService.getTickets(filters);
    return response;
  }
);

export const fetchTicketById = createAsyncThunk(
  'tickets/fetchTicketById',
  async (id: UUID) => {
    const response = await ticketService.getTicketById(id);
    return response;
  }
);

export const createTicket = createAsyncThunk(
  'tickets/createTicket',
  async (data: Partial<Ticket>) => {
    const response = await ticketService.createTicket(data);
    return response;
  }
);

export const updateTicket = createAsyncThunk(
  'tickets/updateTicket',
  async ({ id, data }: { id: UUID; data: Partial<Ticket> }) => {
    const response = await ticketService.updateTicket(id, data);
    return response;
  }
);

export const deleteTicket = createAsyncThunk(
  'tickets/deleteTicket',
  async (id: UUID) => {
    await ticketService.deleteTicket(id);
    return id;
  }
);

export const fetchTicketStats = createAsyncThunk(
  'tickets/fetchTicketStats',
  async () => {
    // Derive stats from ticket list — BFF has no dedicated stats endpoint yet
    const res = await ticketService.getTickets(undefined, 1, 1000);
    const tickets = res.items;
    return {
      total:      tickets.length,
      submitted:  tickets.filter((t) => t.status === 'submitted').length,
      inProgress: tickets.filter((t) => t.status === 'in_progress' || t.status === 'assigned').length,
      resolved:   tickets.filter((t) => t.status === 'resolved').length,
      closed:     tickets.filter((t) => t.status === 'closed').length,
    };
  }
);

export const assignTicket = createAsyncThunk(
  'tickets/assignTicket',
  async ({ ticketId, userId, userName = '' }: { ticketId: UUID; userId: UUID; userName?: string }) => {
    const response = await ticketService.assignTicket(ticketId, userId, userName);
    return response;
  }
);

export const triageTicket = createAsyncThunk(
  'tickets/triageTicket',
  async ({
    ticketId,
    action,
    priority,
    reason,
  }: {
    ticketId: UUID;
    action: 'accept' | 'reject' | 'request_info';
    priority?: string;
    reason?: string;
  }) => {
    const response = await ticketService.triageTicket(ticketId, action, priority, reason);
    return response;
  }
);

export const requestHelp = createAsyncThunk(
  'tickets/requestHelp',
  async ({
    ticketId,
    description,
    suggestedHelperId,
  }: {
    ticketId: UUID;
    description: string;
    suggestedHelperId?: UUID;
  }) => {
    const response = await ticketService.requestHelp(ticketId, description, suggestedHelperId);
    return response;
  }
);

export const assignHelper = createAsyncThunk(
  'tickets/assignHelper',
  async ({ ticketId, helperId, helperName = '' }: { ticketId: UUID; helperId: UUID; helperName?: string }) => {
    const response = await ticketService.assignHelper(ticketId, helperId, helperName);
    return response;
  }
);

export const assignTicketSupport = createAsyncThunk(
  'tickets/assignTicketSupport',
  async ({
    ticketId,
    helpers,
  }: {
    ticketId: UUID;
    helpers: { userId: UUID; userName: string }[];
  }) => {
    const response = await ticketService.assignTicketSupport(ticketId, helpers);
    return response;
  }
);

export const removeHelper = createAsyncThunk(
  'tickets/removeHelper',
  async ({ ticketId, helperId }: { ticketId: UUID; helperId: UUID }) => {
    const response = await ticketService.removeHelper(ticketId, helperId);
    return response;
  }
);

export const updateProgress = createAsyncThunk(
  'tickets/updateProgress',
  async ({ ticketId, percentage, note }: { ticketId: UUID; percentage: number; note?: string }) => {
    const response = await ticketService.updateProgress(ticketId, percentage, note);
    return response;
  }
);

export const updateEstimate = createAsyncThunk(
  'tickets/updateEstimate',
  async ({
    ticketId,
    estimatedCompletionAt,
    note,
  }: {
    ticketId: UUID;
    estimatedCompletionAt: string;
    note?: string;
  }) => {
    const response = await ticketService.updateEstimate(ticketId, estimatedCompletionAt, note);
    return response;
  }
);

export const resolveTicket = createAsyncThunk(
  'tickets/resolveTicket',
  async ({ ticketId, resolutionNote }: { ticketId: UUID; resolutionNote: string }) => {
    const response = await ticketService.resolveTicket(ticketId, resolutionNote);
    return response;
  }
);

export const closeTicket = createAsyncThunk(
  'tickets/closeTicket',
  async ({ ticketId, note }: { ticketId: UUID; note?: string }) => {
    const response = await ticketService.closeTicket(ticketId, note);
    return response;
  }
);

export const reopenTicket = createAsyncThunk(
  'tickets/reopenTicket',
  async ({ ticketId, reason }: { ticketId: UUID; reason: string }) => {
    const response = await ticketService.reopenTicket(ticketId, reason);
    return response;
  }
);

const ticketsSlice = createSlice({
  name: 'tickets',
  initialState,
  reducers: {
    setFilters: (state, action: PayloadAction<TicketFilters>) => {
      state.filters = action.payload;
    },
    setSelectedTicket: (state, action: PayloadAction<Ticket | null>) => {
      state.selectedTicket = action.payload;
    },
    clearError: (state) => {
      state.error = null;
    },
    setPage: (state, action: PayloadAction<number>) => {
      state.pagination.page = action.payload;
    },
    setPageSize: (state, action: PayloadAction<number>) => {
      state.pagination.pageSize = action.payload;
    },
    setStats: (state, action: PayloadAction<TicketsState['stats']>) => {
      state.stats = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch tickets
      .addCase(fetchTickets.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchTickets.fulfilled, (state, action) => {
        state.loading = false;
        state.items = action.payload.items;
        state.pagination.totalCount = action.payload.total;
        state.pagination.page = action.payload.page;
        state.pagination.pageSize = action.payload.pageSize;
      })
      .addCase(fetchTickets.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || 'Failed to fetch tickets';
      })
      // Fetch single ticket
      .addCase(fetchTicketById.fulfilled, (state, action) => {
        state.selectedTicket = action.payload;
      })
      // Create ticket
      .addCase(createTicket.fulfilled, (state, action) => {
        state.items.unshift(action.payload);
        state.pagination.totalCount += 1;
      })
      // Update ticket
      .addCase(updateTicket.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTicket?.id === action.payload.id) {
          state.selectedTicket = action.payload;
        }
      })
      // Delete ticket
      .addCase(deleteTicket.fulfilled, (state, action) => {
        state.items = state.items.filter((t) => t.id !== action.payload);
        state.pagination.totalCount -= 1;
        if (state.selectedTicket?.id === action.payload) {
          state.selectedTicket = null;
        }
      })
      // Fetch stats
      .addCase(fetchTicketStats.fulfilled, (state, action) => {
        state.stats = action.payload;
      })
      // Assign ticket
      .addCase(assignTicket.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTicket?.id === action.payload.id) {
          state.selectedTicket = action.payload;
        }
      })
      // Triage ticket
      .addCase(triageTicket.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTicket?.id === action.payload.id) {
          state.selectedTicket = action.payload;
        }
      })
      // Request help
      .addCase(requestHelp.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTicket?.id === action.payload.id) {
          state.selectedTicket = action.payload;
        }
      })
      // Assign helper
      .addCase(assignHelper.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTicket?.id === action.payload.id) {
          state.selectedTicket = action.payload;
        }
      })
      // Assign ticket support (multiple helpers)
      .addCase(assignTicketSupport.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTicket?.id === action.payload.id) {
          state.selectedTicket = action.payload;
        }
      })
      // Remove helper
      .addCase(removeHelper.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) {
          state.items[index] = action.payload;
        }
        if (state.selectedTicket?.id === action.payload.id) {
          state.selectedTicket = action.payload;
        }
      })
      // Update progress
      .addCase(updateProgress.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) state.items[index] = action.payload;
        if (state.selectedTicket?.id === action.payload.id) state.selectedTicket = action.payload;
      })
      // Update estimate
      .addCase(updateEstimate.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) state.items[index] = action.payload;
        if (state.selectedTicket?.id === action.payload.id) state.selectedTicket = action.payload;
      })
      // Resolve ticket
      .addCase(resolveTicket.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) state.items[index] = action.payload;
        if (state.selectedTicket?.id === action.payload.id) state.selectedTicket = action.payload;
      })
      // Close ticket
      .addCase(closeTicket.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) state.items[index] = action.payload;
        if (state.selectedTicket?.id === action.payload.id) state.selectedTicket = action.payload;
      })
      // Reopen ticket
      .addCase(reopenTicket.fulfilled, (state, action) => {
        const index = state.items.findIndex((t) => t.id === action.payload.id);
        if (index !== -1) state.items[index] = action.payload;
        if (state.selectedTicket?.id === action.payload.id) state.selectedTicket = action.payload;
      });
  },
});

export const { setFilters, setSelectedTicket, clearError, setPage, setPageSize, setStats } = ticketsSlice.actions;
export default ticketsSlice.reducer;
