import React, { useState } from 'react';
import { Button } from '../../../components/common/Button';
import { Slideout } from '../../../components/common/Slideout';
import { UUID } from '../../../models/common';
import { User } from '../../../models/User';
import { SupportRequest } from '../../../models/Task';
import { useAppToast } from '../../../hooks/useAppToast';
import styles from './AssignCollaboratorModal.module.css';

interface AssignCollaboratorModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (collaborators: {
    userId: UUID;
    userName: string;
    role: 'support' | 'reviewer' | 'contributor';
    effortPercentage: number;
  }[]) => Promise<void>;
  supportRequest?: SupportRequest;
  taskTitle: string;
  /** Real users loaded from the store — passed by TaskActions */
  availableUsers?: User[];
}

const getAvatarInitials = (name: string) =>
  name.split(' ').map((n) => n[0]).join('').toUpperCase().substring(0, 2);

const AssignCollaboratorModal: React.FC<AssignCollaboratorModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
  supportRequest,
  taskTitle,
  availableUsers = [],
}) => {
  const [selectedStaff, setSelectedStaff] = useState<UUID[]>([]);
  const [role, setRole] = useState<'support' | 'reviewer' | 'contributor'>('support');
  const [effortPercentage, setEffortPercentage] = useState(30);
  const [submitting, setSubmitting] = useState(false);
  const toast = useAppToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedStaff.length === 0) return;

    setSubmitting(true);
    try {
      const collaborators = selectedStaff.map((userId) => {
        const user = availableUsers.find((u) => u.id === userId);
        return {
          userId,
          userName: user?.fullName || '',
          role,
          effortPercentage: Math.floor(effortPercentage / selectedStaff.length),
        };
      });

      await onSubmit(collaborators);
      handleClose();
    } catch (error: unknown) {
      toast.fromError(error, 'Đã có lỗi khi phân công, vui lòng thử lại');
    } finally {
      setSubmitting(false);
    }
  };

  const handleClose = () => {
    setSelectedStaff([]);
    setRole('support');
    setEffortPercentage(30);
    onClose();
  };

  const toggleStaff = (userId: UUID) => {
    setSelectedStaff((prev) =>
      prev.includes(userId)
        ? prev.filter((id) => id !== userId)
        : [...prev, userId]
    );
  };

  const getAvatarColor = (index: number) => {
    const colors = [
      'var(--blue-500)',
      'var(--green-500)',
      'var(--purple-500)',
      'var(--orange-500)',
    ];
    return colors[index % colors.length];
  };

  return (
    <Slideout
      isOpen={isOpen}
      onClose={handleClose}
      title={
        <>
          <i className="fas fa-user-plus"></i> Chỉ định Collaborator
        </>
      }
      width="700px"
    >
      <form onSubmit={handleSubmit}>
        <div className={styles.modalBody}>
            <div className={styles.infoBox}>
              <i className="fas fa-info-circle"></i>
              <div>
                <strong>Task:</strong> {taskTitle}
                {supportRequest && (
                  <>
                    <p className={styles.requestDescription}>
                      <strong>Yêu cầu hỗ trợ:</strong> {supportRequest.description}
                    </p>
                    <p className={styles.requestReason}>
                      <strong>Lý do:</strong> {supportRequest.reason}
                    </p>
                  </>
                )}
              </div>
            </div>

            <div className={styles.formGroup}>
              <label className={styles.label}>
                Chọn Collaborator <span className={styles.required}>*</span>
              </label>
              <div className={styles.staffList}>
                {availableUsers.length === 0 ? (
                  <div className={styles.emptyStaff}>
                    <i className="fas fa-users-slash"></i>
                    <span>Không có nhân viên nào</span>
                  </div>
                ) : (
                  availableUsers.map((user, index) => (
                    <div
                      key={user.id}
                      className={`${styles.staffCard} ${
                        selectedStaff.includes(user.id) ? styles.selected : ''
                      }`}
                      onClick={() => toggleStaff(user.id)}
                    >
                      <div className={styles.staffInfo}>
                        <div
                          className={styles.avatar}
                          style={{ backgroundColor: getAvatarColor(index) }}
                        >
                          {getAvatarInitials(user.fullName)}
                        </div>
                        <div className={styles.staffDetails}>
                          <div className={styles.staffName}>{user.fullName}</div>
                          <div className={styles.staffSkills}>
                            {(user.skills ?? []).slice(0, 3).map((skill, idx) => (
                              <span key={idx} className={styles.skillBadge}>
                                {skill}
                              </span>
                            ))}
                          </div>
                          <div className={styles.staffWorkload}>
                            {user.departmentName}
                          </div>
                        </div>
                      </div>
                      <div className={styles.checkbox}>
                        {selectedStaff.includes(user.id) && (
                          <i className="fas fa-check"></i>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            <div className={styles.formRow}>
              <div className={styles.formGroup}>
                <label className={styles.label}>Vai trò</label>
                <select
                  className={styles.select}
                  value={role}
                  onChange={(e) => setRole(e.target.value as any)}
                >
                  <option value="support">Hỗ trợ (Support)</option>
                  <option value="contributor">Đóng góp (Contributor)</option>
                  <option value="reviewer">Đánh giá (Reviewer)</option>
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.label}>Effort %</label>
                <div className={styles.effortInput}>
                  <input
                    type="number"
                    min="5"
                    max="50"
                    step="5"
                    value={effortPercentage}
                    onChange={(e) => setEffortPercentage(Number(e.target.value))}
                    className={styles.numberInput}
                  />
                  <span className={styles.effortUnit}>%</span>
                </div>
              </div>
            </div>

            {selectedStaff.length > 0 && (
              <div className={styles.selectedSummary}>
                <i className="fas fa-users"></i>
                <span>
                  Đã chọn {selectedStaff.length} collaborator(s) - mỗi người ~
                  {Math.floor(effortPercentage / selectedStaff.length)}% effort
                </span>
              </div>
            )}
          </div>

          <div className={styles.modalFooter}>
            <Button
              type="button"
              variant="secondary"
              onClick={handleClose}
              disabled={submitting}
            >
              Hủy
            </Button>
            <Button
              type="submit"
              variant="primary"
              disabled={selectedStaff.length === 0 || submitting}
            >
              {submitting ? (
                <>
                  <i className="fas fa-spinner fa-spin"></i> Đang chỉ định...
                </>
              ) : (
                <>
                  <i className="fas fa-user-check"></i> Chỉ định Collaborator
                </>
              )}
            </Button>
          </div>
        </form>
      </Slideout>
    );
  };

export default AssignCollaboratorModal;
