import React from 'react';
import styles from './ZoomControls.module.css';

interface ZoomControlsProps {
  zoom: number;
  onZoomIn: () => void;
  onZoomOut: () => void;
  onResetZoom: () => void;
  onFullscreen?: () => void;
  minZoom?: number;
  maxZoom?: number;
}

export const ZoomControls: React.FC<ZoomControlsProps> = ({
  zoom,
  onZoomIn,
  onZoomOut,
  onResetZoom,
  onFullscreen,
  minZoom = 0.5,
  maxZoom = 2,
}) => {
  return (
    <div className={styles.controls}>
      <button
        className={styles.controlButton}
        onClick={onZoomOut}
        title="Thu nhỏ"
        disabled={zoom <= minZoom}
      >
        −
      </button>
      <button
        className={styles.controlButton}
        onClick={onResetZoom}
        title="Đặt lại"
      >
        {Math.round(zoom * 100)}%
      </button>
      <button
        className={styles.controlButton}
        onClick={onZoomIn}
        title="Phóng to"
        disabled={zoom >= maxZoom}
      >
        +
      </button>
      {onFullscreen && (
        <button
          className={styles.controlButton}
          onClick={onFullscreen}
          title="Toàn màn hình"
        >
          ⛶
        </button>
      )}
    </div>
  );
};
