import React, { useRef, useState } from 'react';
import { IconButton } from '../IconButton';
import styles from './FileUploadArea.module.css';

export interface FileUploadAreaProps {
  value: File[];
  onChange: (files: File[]) => void;
  accept?: string;
  maxSize?: number; // in MB
  maxFiles?: number;
  disabled?: boolean;
}

export const FileUploadArea: React.FC<FileUploadAreaProps> = ({
  value,
  onChange,
  accept = '*/*',
  maxSize = 10,
  maxFiles = 5,
  disabled = false,
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [error, setError] = useState<string>('');
  const inputRef = useRef<HTMLInputElement>(null);

  const validateFile = (file: File): string | null => {
    // Check file size
    const sizeInMB = file.size / (1024 * 1024);
    if (sizeInMB > maxSize) {
      return `File "${file.name}" vượt quá ${maxSize}MB`;
    }

    // Check file type if accept is specified
    if (accept !== '*/*') {
      const acceptTypes = accept.split(',').map((t) => t.trim());
      const fileType = file.type;
      const fileExt = `.${file.name.split('.').pop()}`;

      const isAccepted = acceptTypes.some((type) => {
        if (type.endsWith('/*')) {
          return fileType.startsWith(type.replace('/*', ''));
        }
        return type === fileType || type === fileExt;
      });

      if (!isAccepted) {
        return `File "${file.name}" không đúng định dạng cho phép`;
      }
    }

    return null;
  };

  const handleFiles = (newFiles: FileList | null) => {
    if (!newFiles || newFiles.length === 0) return;

    setError('');

    const filesArray = Array.from(newFiles);
    const totalFiles = value.length + filesArray.length;

    if (totalFiles > maxFiles) {
      setError(`Chỉ được tải lên tối đa ${maxFiles} file`);
      return;
    }

    // Validate all files
    for (const file of filesArray) {
      const validationError = validateFile(file);
      if (validationError) {
        setError(validationError);
        return;
      }
    }

    // Filter out duplicates
    const newUniqueFiles = filesArray.filter(
      (newFile) => !value.some((existingFile) => existingFile.name === newFile.name)
    );

    if (newUniqueFiles.length === 0) {
      setError('File đã tồn tại trong danh sách');
      return;
    }

    onChange([...value, ...newUniqueFiles]);
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();

    if (disabled) return;

    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (disabled) return;

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (disabled) return;
    handleFiles(e.target.files);
    // Reset input value to allow selecting same file again
    if (inputRef.current) {
      inputRef.current.value = '';
    }
  };

  const handleRemove = (index: number) => {
    const newFiles = value.filter((_, i) => i !== index);
    onChange(newFiles);
    setError('');
  };

  const handleClick = () => {
    if (disabled) return;
    inputRef.current?.click();
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const getFileIcon = (fileName: string): string => {
    const ext = fileName.split('.').pop()?.toLowerCase();
    switch (ext) {
      case 'pdf':
        return 'fa-file-pdf';
      case 'doc':
      case 'docx':
        return 'fa-file-word';
      case 'xls':
      case 'xlsx':
        return 'fa-file-excel';
      case 'jpg':
      case 'jpeg':
      case 'png':
      case 'gif':
        return 'fa-file-image';
      case 'zip':
      case 'rar':
        return 'fa-file-archive';
      default:
        return 'fa-file';
    }
  };

  return (
    <div className={styles.container}>
      <div
        className={`${styles.dropzone} ${dragActive ? styles.active : ''} ${
          disabled ? styles.disabled : ''
        }`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={handleClick}
      >
        <input
          ref={inputRef}
          type="file"
          multiple
          accept={accept}
          onChange={handleChange}
          disabled={disabled}
          style={{ display: 'none' }}
        />

        <div className={styles.dropzoneContent}>
          <i className={`fas fa-cloud-upload-alt ${styles.uploadIcon}`}></i>
          <p className={styles.dropzoneText}>
            <strong>Kéo thả file vào đây</strong> hoặc click để chọn
          </p>
          <p className={styles.dropzoneHint}>
            Tối đa {maxFiles} file, mỗi file không quá {maxSize}MB
          </p>
        </div>
      </div>

      {error && (
        <div className={styles.error}>
          <i className="fas fa-exclamation-circle"></i>
          {error}
        </div>
      )}

      {value.length > 0 && (
        <div className={styles.fileList}>
          {value.map((file, index) => (
            <div key={`${file.name}-${index}`} className={styles.fileItem}>
              <div className={styles.fileIcon}>
                <i className={`fas ${getFileIcon(file.name)}`}></i>
              </div>
              <div className={styles.fileInfo}>
                <span className={styles.fileName}>{file.name}</span>
                <span className={styles.fileSize}>{formatFileSize(file.size)}</span>
              </div>
              <IconButton
                icon="fas fa-times"
                size="sm"
                variant="danger"
                onClick={() => handleRemove(index)}
                disabled={disabled}
                ariaLabel="Xóa file"
              />
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
