/**
 * HistoryPage Component
 * Main container for Work History feature.
 * Uses server-side pagination with IntersectionObserver-based infinite scroll.
 */

import React, { useState, useEffect, useRef } from 'react';
import { historyService } from '../../services/historyService';
import { HistoryItem, HistoryStats, HistoryItemType, groupHistoryByDate } from '../../models/History';
import { TicketPriority } from '../../models/Ticket';
import { TaskPriority } from '../../models/Task';
import { useAppToast } from '../../hooks/useAppToast';
import { HistoryStatsCards } from '../../components/history/HistoryStatsCards';
import { HistoryFilters } from '../../components/history/HistoryFilters';
import { HistoryTimeline } from '../../components/history/HistoryTimeline';
import { Button, TableCard } from '../../components/common';
import styles from './HistoryPage.module.css';

const PAGE_SIZE = 20;

/** Pure utility — lives outside the component to avoid stale-closure issues. */
function getDateRangeFilter(range: string): { from: Date; to: Date } {
  const now  = new Date();
  const from = new Date();
  switch (range) {
    case 'today':   from.setHours(0, 0, 0, 0); break;
    case 'week':    from.setDate(now.getDate() - 7); break;
    case 'month':   from.setMonth(now.getMonth() - 1); break;
    case 'quarter': from.setMonth(now.getMonth() - 3); break;
    case 'year':    from.setFullYear(now.getFullYear() - 1); break;
    default:        from.setFullYear(2000);
  }
  return { from, to: now };
}

const HistoryPage: React.FC = () => {
  const toast = useAppToast();
  // ── Accumulated item list ─────────────────────────────────────────────────
  const [historyItems, setHistoryItems] = useState<HistoryItem[]>([]);
  const [stats,        setStats]        = useState<HistoryStats | null>(null);
  const [hasMore,      setHasMore]      = useState(false);
  const [loading,      setLoading]      = useState(true);   // first-page load
  const [loadingMore,  setLoadingMore]  = useState(false);  // subsequent pages
  const [error,        setError]        = useState<string | null>(null);

  // ── Filters ───────────────────────────────────────────────────────────────
  const [search,    setSearch]    = useState('');
  const [dateRange, setDateRange] = useState<string>('month');
  const [itemType,  setItemType]  = useState<HistoryItemType | ''>('');
  const [priority,  setPriority]  = useState<TicketPriority | TaskPriority | ''>('');

  // ── Pagination trigger ────────────────────────────────────────────────────
  // filterVersion increments whenever server-side filters change → fresh load.
  const [filterVersion, setFilterVersion] = useState(0);
  const [page,          setPage]          = useState(1);

  // Refs expose current filter values inside the load effect without re-subscribing.
  const dateRangeRef = useRef(dateRange);
  const itemTypeRef  = useRef(itemType);
  const priorityRef  = useRef(priority);

  // Sentinel div watched by IntersectionObserver at the bottom of the list.
  const sentinelRef      = useRef<HTMLDivElement>(null);
  const isInitialMount   = useRef(true);

  // ── Stats: load once ──────────────────────────────────────────────────────
  useEffect(() => {
    historyService.getStats().then(setStats).catch((err: unknown) => {
      // Stats are non-critical, don't show a toast — just log
      console.warn('[HistoryPage] Failed to load stats:', err);
    });
  }, []);

  // ── Filter change → reset to page 1 ──────────────────────────────────────
  useEffect(() => {
    // On initial mount, just populate refs and bail — the load effect handles mount.
    if (isInitialMount.current) {
      isInitialMount.current = false;
      dateRangeRef.current = dateRange;
      itemTypeRef.current  = itemType;
      priorityRef.current  = priority;
      return;
    }
    dateRangeRef.current = dateRange;
    itemTypeRef.current  = itemType;
    priorityRef.current  = priority;

    setHistoryItems([]);
    setHasMore(false);
    setLoading(true);
    setError(null);
    // setPage(1) alone won't retrigger the load effect if page was already 1,
    // so we always bump filterVersion to guarantee a fresh fetch.
    setPage(1);
    setFilterVersion((v) => v + 1);
  }, [dateRange, itemType, priority]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Load page ─────────────────────────────────────────────────────────────
  // Deps: [filterVersion, page]  — reads current filters via refs.
  useEffect(() => {
    let cancelled = false;
    const isFirstPage = page === 1;

    if (!isFirstPage) setLoadingMore(true);

    const filters: Parameters<typeof historyService.getHistory>[0] = {};
    const dr = dateRangeRef.current;
    const it = itemTypeRef.current;
    const pr = priorityRef.current;
    if (it) filters.type     = it as HistoryItemType;
    if (pr) filters.priority = pr;
    if (dr && dr !== 'all')  filters.dateRange = getDateRangeFilter(dr);

    historyService
      .getHistory(filters, page, PAGE_SIZE)
      .then((result) => {
        if (cancelled) return;
        setHistoryItems((prev) =>
          isFirstPage ? result.items : [...prev, ...result.items],
        );
        setHasMore(page < result.totalPages);
        setLoading(false);
        setLoadingMore(false);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        toast.fromError(err, 'Không thể tải dữ liệu lịch sử');
        setError('Không thể tải dữ liệu lịch sử');
        setLoading(false);
        setLoadingMore(false);
      });

    return () => { cancelled = true; };
  }, [filterVersion, page]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── IntersectionObserver: trigger next page when sentinel enters viewport ─
  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore && !loadingMore && !loading) {
          setPage((prev) => prev + 1);
        }
      },
      { threshold: 0.1, rootMargin: '120px' },
    );

    observer.observe(sentinel);
    return () => observer.disconnect();
  }, [hasMore, loadingMore, loading]);

  // ── Export ────────────────────────────────────────────────────────────────
  const handleExport = async () => {
    try {
      const blob = await historyService.exportReport({
        format: 'csv',
        dateRange: dateRange !== 'all' ? getDateRangeFilter(dateRange) : undefined,
        includeStats: true,
      });
      const url  = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href  = url;
      link.download = `work-history-${dateRange}.csv`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể xuất báo cáo, vui lòng thử lại');
    }
  };

  // ── Client-side search (applied to accumulated items) ────────────────────
  const filteredItems = search
    ? historyItems.filter((item) => {
        const q = search.toLowerCase();
        return (
          item.entityCode.toLowerCase().includes(q) ||
          item.entityTitle.toLowerCase().includes(q) ||
          item.actionDescription.toLowerCase().includes(q)
        );
      })
    : historyItems;

  const groupedHistory = groupHistoryByDate(filteredItems);

  // ── Full-page states (initial load only) ─────────────────────────────────
  if (loading && historyItems.length === 0) {
    return (
      <div className={styles.loading}>
        <i className="fas fa-spinner fa-spin"></i>
        <p>Đang tải dữ liệu...</p>
      </div>
    );
  }

  if (error && historyItems.length === 0) {
    return (
      <div className={styles.error}>
        <i className="fas fa-exclamation-circle"></i>
        <p>{error}</p>
        <button
          onClick={() => setFilterVersion((v) => v + 1)}
          className={styles.retryButton}
        >
          <i className="fas fa-redo"></i> Thử lại
        </button>
      </div>
    );
  }

  return (
    <div className={styles.historyPage}>
      {/* Page Header */}
      <div className={styles.pageHeader}>
        <div>
          <h1 className={styles.pageTitle}>
            <i className="fas fa-history"></i>
            Lịch sử Công việc
          </h1>
          <p className={styles.pageDescription}>
            Xem lại các công việc đã hoàn thành
          </p>
        </div>
        <div className={styles.pageActions}>
          <Button variant="secondary" onClick={handleExport}>
            <i className="fas fa-download"></i> Xuất báo cáo
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      {stats && <HistoryStatsCards stats={stats} />}

      {/* Table Card: Filters header + Timeline (no footer pagination) */}
      <TableCard
        header={
          <HistoryFilters
            search={search}
            onSearchChange={setSearch}
            dateRange={dateRange}
            onDateRangeChange={setDateRange}
            itemType={itemType}
            onItemTypeChange={setItemType}
            priority={priority}
            onPriorityChange={setPriority}
          />
        }
      >
        {!loading && filteredItems.length === 0 ? (
          <div className={styles.emptyState}>
            <i className="fas fa-inbox"></i>
            <h3>Không có dữ liệu lịch sử</h3>
            <p>
              {search
                ? 'Không tìm thấy kết quả phù hợp với tìm kiếm của bạn'
                : 'Chưa có công việc nào được hoàn thành'}
            </p>
          </div>
        ) : (
          <HistoryTimeline
            groupedHistory={groupedHistory}
            loading={loading && historyItems.length === 0}
          />
        )}

        {/* Inline "loading more" row */}
        {loadingMore && (
          <div className={styles.loadingMore}>
            <i className="fas fa-spinner fa-spin"></i>
            <span>Đang tải thêm...</span>
          </div>
        )}
      </TableCard>

      {/* Sentinel: IntersectionObserver trigger — sits just below the card */}
      <div ref={sentinelRef} className={styles.sentinel} aria-hidden="true" />

      {/* All-loaded indicator */}
      {!hasMore && historyItems.length > 0 && !loading && (
        <div className={styles.allLoaded}>
          <i className="fas fa-check-circle"></i>
          Đã tải tất cả {historyItems.length} hoạt động
        </div>
      )}
    </div>
  );
};

export default HistoryPage;

