import { configureStore } from '@reduxjs/toolkit';
import authReducer from './slices/authSlice';
import ticketsReducer from './slices/ticketsSlice';
import tasksReducer from './slices/tasksSlice';
import usersReducer from './slices/usersSlice';
import uiReducer from './slices/uiSlice';
import dashboardReducer from './slices/dashboardSlice';
import managerDashboardReducer from './slices/managerDashboardSlice';
import approvalsReducer from './slices/approvalsSlice';
import slaAlertsReducer from './slices/slaAlertsSlice';
import notificationsReducer from './slices/notificationSlice';
import medicalIncidentsReducer from './slices/medicalIncidentsSlice';

export const store = configureStore({
  reducer: {
    auth: authReducer,
    tickets: ticketsReducer,
    tasks: tasksReducer,
    users: usersReducer,
    ui: uiReducer,
    dashboard: dashboardReducer,
    managerDashboard: managerDashboardReducer,
    approvals: approvalsReducer,
    slaAlerts: slaAlertsReducer,
    notifications: notificationsReducer,
    medicalIncidents: medicalIncidentsReducer,
  },
  devTools: process.env.NODE_ENV !== 'production',
});

export type RootState = ReturnType<typeof store.getState>;
export type AppDispatch = typeof store.dispatch;
