/**
 * Admin service facade.
 *
 * Endpoint reference: web-bff/api/v1/admin
 */

import { adminEndpoint } from './endpoint';
import type {
  GetAccountsRequest,
  AssignPackageToUserRequest,
  SetAccountStatusRequest,
  CreatePermissionRequest,
  UpdatePermissionRequest,
  CreatePackageRequest,
  UpdatePackageRequest,
  AssignPermissionsToPackageRequest,
} from './requestModel';

export const adminService = {
  // ── Accounts ───────────────────────────────────────────────────────────────────

  getAccounts: (params?: GetAccountsRequest) => adminEndpoint.getAccounts(params),

  getAccountDetail: (id: string) => adminEndpoint.getAccountDetail(id),

  getAccountPackages: (id: string) => adminEndpoint.getAccountPackages(id),

  assignPackage: (userId: string, req: AssignPackageToUserRequest) =>
    adminEndpoint.assignPackageToAccount(userId, req),

  removePackage: (userId: string, assignmentId: string) =>
    adminEndpoint.removePackageFromAccount(userId, assignmentId),

  setAccountStatus: (userId: string, req: SetAccountStatusRequest) =>
    adminEndpoint.setAccountStatus(userId, req),

  // ── Permissions ──────────────────────────────────────────────────────────────────

  getPermissions: () => adminEndpoint.getPermissions(),

  createPermission: (req: CreatePermissionRequest) => adminEndpoint.createPermission(req),

  updatePermission: (id: string, req: UpdatePermissionRequest) =>
    adminEndpoint.updatePermission(id, req),

  deletePermission: (id: string) => adminEndpoint.deletePermission(id),

  // ── Feature Packages ──────────────────────────────────────────────────────────────────

  getPackages: () => adminEndpoint.getPackages(),

  createPackage: (req: CreatePackageRequest) => adminEndpoint.createPackage(req),

  updatePackage: (id: string, req: UpdatePackageRequest) =>
    adminEndpoint.updatePackage(id, req),

  deletePackage: (id: string) => adminEndpoint.deletePackage(id),

  assignPermissionsToPackage: (packageId: string, req: AssignPermissionsToPackageRequest) =>
    adminEndpoint.assignPermissionsToPackage(packageId, req),

  removePermissionFromPackage: (packageId: string, permissionId: string) =>
    adminEndpoint.removePermissionFromPackage(packageId, permissionId),
};

// Re-export request model types for convenience
export type {
  GetAccountsRequest,
  AssignPackageToUserRequest,
  SetAccountStatusRequest,
  CreatePermissionRequest,
  UpdatePermissionRequest,
  CreatePackageRequest,
  UpdatePackageRequest,
  AssignPermissionsToPackageRequest,
} from './requestModel';

