import React, { useState, useEffect } from 'react';
import './CountdownTimer.css';

interface CountdownTimerProps {
  deadline: string; // ISO date string
  className?: string;
}

export const CountdownTimer: React.FC<CountdownTimerProps> = ({ deadline, className }) => {
  const [timeRemaining, setTimeRemaining] = useState<{
    hours: number;
    minutes: number;
    seconds: number;
    isOverdue: boolean;
  }>(() => calculateTimeRemaining(deadline));

  useEffect(() => {
    // Update every second
    const interval = setInterval(() => {
      setTimeRemaining(calculateTimeRemaining(deadline));
    }, 1000);

    return () => clearInterval(interval);
  }, [deadline]);

  const { hours, minutes, seconds, isOverdue } = timeRemaining;

  if (isOverdue) {
    return (
      <div className={`countdown-timer countdown-overdue ${className || ''}`}>
        <span className="countdown-icon">⚠️</span>
        <span className="countdown-text">Quá hạn {Math.abs(hours)}h {Math.abs(minutes)}p</span>
      </div>
    );
  }

  return (
    <div className={`countdown-timer ${className || ''}`}>
      <span className="countdown-icon">⏰</span>
      <span className="countdown-text">
        {hours > 0 && `${hours}h `}
        {minutes}p {seconds}s
      </span>
    </div>
  );
};

function calculateTimeRemaining(deadline: string) {
  const now = new Date().getTime();
  const deadlineTime = new Date(deadline).getTime();
  const diff = deadlineTime - now;

  const isOverdue = diff < 0;
  const absDiff = Math.abs(diff);

  const hours = Math.floor(absDiff / (1000 * 60 * 60));
  const minutes = Math.floor((absDiff % (1000 * 60 * 60)) / (1000 * 60));
  const seconds = Math.floor((absDiff % (1000 * 60)) / 1000);

  return { hours, minutes, seconds, isOverdue };
}
