/**
 * Real BFF API calls for Admin management endpoints.
 * Base route: /web-bff/api/v1/admin
 */

import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type {
  BffAccountListItemDto,
  BffAccountDetailDto,
  BffAccountPackageSummaryDto,
  BffPermissionDto,
  BffFeaturePackageDto,
  BffPagedResultDto,
} from './responseModel';
import type {
  GetAccountsRequest,
  AssignPackageToUserRequest,
  SetAccountStatusRequest,
  CreatePermissionRequest,
  UpdatePermissionRequest,
  CreatePackageRequest,
  UpdatePackageRequest,
  AssignPermissionsToPackageRequest,
} from './requestModel';

// ─── Accounts ────────────────────────────────────────────────────────────────

export const adminEndpoint = {
  // ── Accounts ──────────────────────────────────────────────────────────────

  /** GET /admin/accounts?search=&role=&isActive=&page=&pageSize= */
  getAccounts: async (
    params: GetAccountsRequest = {},
  ): Promise<BffPagedResultDto<BffAccountListItemDto>> => {
    const qs = new URLSearchParams();
    if (params.search)                       qs.set('search', params.search);
    if (params.role)                         qs.set('role', params.role);
    if (params.isActive !== undefined)       qs.set('isActive', String(params.isActive));
    if (params.page !== undefined)           qs.set('page', String(params.page));
    if (params.pageSize !== undefined)       qs.set('pageSize', String(params.pageSize));
    const query = qs.toString() ? `?${qs}` : '';
    const res = await apiClient.get<BffResponse<BffPagedResultDto<BffAccountListItemDto>>>(
      `/admin/accounts${query}`,
    );
    return unwrap(res);
  },

  /** GET /admin/accounts/{id} */
  getAccountDetail: async (id: string): Promise<BffAccountDetailDto> => {
    const res = await apiClient.get<BffResponse<BffAccountDetailDto>>(
      `/admin/accounts/${id}`,
    );
    return unwrap(res);
  },

  /** GET /admin/accounts/{id}/packages */
  getAccountPackages: async (id: string): Promise<BffAccountPackageSummaryDto[]> => {
    const res = await apiClient.get<BffResponse<BffAccountPackageSummaryDto[]>>(
      `/admin/accounts/${id}/packages`,
    );
    return unwrap(res);
  },

  /** POST /admin/accounts/{id}/packages */
  assignPackageToAccount: async (
    userId: string,
    req: AssignPackageToUserRequest,
  ): Promise<BffAccountPackageSummaryDto> => {
    const res = await apiClient.post<BffResponse<BffAccountPackageSummaryDto>>(
      `/admin/accounts/${userId}/packages`,
      req,
    );
    return unwrap(res);
  },

  /** DELETE /admin/accounts/{id}/packages/{assignmentId} */
  removePackageFromAccount: async (userId: string, assignmentId: string): Promise<void> => {
    await apiClient.delete<BffResponse<object>>(
      `/admin/accounts/${userId}/packages/${assignmentId}`,
    );
  },

  /** PATCH /admin/accounts/{id}/status */
  setAccountStatus: async (
    userId: string,
    req: SetAccountStatusRequest,
  ): Promise<void> => {
    await apiClient.patch<BffResponse<object>>(
      `/admin/accounts/${userId}/status`,
      req,
    );
  },

  // ── Permissions ───────────────────────────────────────────────────────────

  /** GET /admin/permissions */
  getPermissions: async (): Promise<BffPermissionDto[]> => {
    const res = await apiClient.get<BffResponse<BffPermissionDto[]>>('/admin/permissions');
    return unwrap(res);
  },

  /** GET /admin/permissions/{id} */
  getPermission: async (id: string): Promise<BffPermissionDto> => {
    const res = await apiClient.get<BffResponse<BffPermissionDto>>(`/admin/permissions/${id}`);
    return unwrap(res);
  },

  /** POST /admin/permissions */
  createPermission: async (req: CreatePermissionRequest): Promise<BffPermissionDto> => {
    const res = await apiClient.post<BffResponse<BffPermissionDto>>('/admin/permissions', req);
    return unwrap(res);
  },

  /** PUT /admin/permissions/{id} */
  updatePermission: async (id: string, req: UpdatePermissionRequest): Promise<BffPermissionDto> => {
    const res = await apiClient.put<BffResponse<BffPermissionDto>>(`/admin/permissions/${id}`, req);
    return unwrap(res);
  },

  /** DELETE /admin/permissions/{id} */
  deletePermission: async (id: string): Promise<void> => {
    await apiClient.delete<BffResponse<object>>(`/admin/permissions/${id}`);
  },

  // ── Feature Packages ──────────────────────────────────────────────────────

  /** GET /admin/packages */
  getPackages: async (): Promise<BffFeaturePackageDto[]> => {
    const res = await apiClient.get<BffResponse<BffFeaturePackageDto[]>>('/admin/packages');
    return unwrap(res);
  },

  /** GET /admin/packages/{id} */
  getPackage: async (id: string): Promise<BffFeaturePackageDto> => {
    const res = await apiClient.get<BffResponse<BffFeaturePackageDto>>(`/admin/packages/${id}`);
    return unwrap(res);
  },

  /** POST /admin/packages */
  createPackage: async (req: CreatePackageRequest): Promise<BffFeaturePackageDto> => {
    const res = await apiClient.post<BffResponse<BffFeaturePackageDto>>('/admin/packages', req);
    return unwrap(res);
  },

  /** PUT /admin/packages/{id} */
  updatePackage: async (id: string, req: UpdatePackageRequest): Promise<BffFeaturePackageDto> => {
    const res = await apiClient.put<BffResponse<BffFeaturePackageDto>>(`/admin/packages/${id}`, req);
    return unwrap(res);
  },

  /** DELETE /admin/packages/{id} */
  deletePackage: async (id: string): Promise<void> => {
    await apiClient.delete<BffResponse<object>>(`/admin/packages/${id}`);
  },

  /** PUT /admin/packages/{id}/permissions — replaces all permissions */
  assignPermissionsToPackage: async (
    packageId: string,
    req: AssignPermissionsToPackageRequest,
  ): Promise<void> => {
    await apiClient.put<BffResponse<object>>(`/admin/packages/${packageId}/permissions`, req);
  },

  /** DELETE /admin/packages/{id}/permissions/{permissionId} */
  removePermissionFromPackage: async (packageId: string, permissionId: string): Promise<void> => {
    await apiClient.delete<BffResponse<object>>(
      `/admin/packages/${packageId}/permissions/${permissionId}`,
    );
  },
};
