import React, { useState, useEffect, ReactNode } from 'react';
import { useResponsive } from '../../../hooks/useResponsive';
import styles from './TabSlideout.module.css';

export interface TabSlideoutProps {
  children: ReactNode;
  defaultHeight?: string;
  tabContentMaxHeight?: string;
  /**
   * Optional custom class name for the container
   */
  className?: string;
  /**
   * Optional footer content that will be sticky at the bottom when expanded
   */
  footer?: ReactNode;
  /**
   * Whether to show the expand/collapse button
   */
  showExpandButton?: boolean;
}

/**
 * TabSlideout - A reusable wrapper component for tab contents that provides:
 * - Expand/Collapse functionality
 * - Slide-out panel on desktop (from right)
 * - Slide-up panel on mobile (from bottom)
 * - Backdrop overlay
 * - Body scroll lock when expanded on mobile
 * 
 * Usage:
 * ```tsx
 * <TabSlideout footer={<YourFooterContent />}>
 *   <YourTabContent />
 * </TabSlideout>
 * ```
 */
export const TabSlideout: React.FC<TabSlideoutProps> = ({
  children,
  defaultHeight = '600px',
  tabContentMaxHeight = null,
  className = '',
  footer,
  showExpandButton = true,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const { isMobile } = useResponsive();

  // Prevent body scroll when expanded on mobile
  useEffect(() => {
    if (isExpanded && isMobile) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [isExpanded, isMobile]);

  const toggleExpand = () => {
    setIsExpanded(!isExpanded);
  };

  const containerClassName = `${styles.container} ${isExpanded ? styles.expanded : ''} ${className}`;

  return (
    <>
      {/* Backdrop */}
      {isExpanded && (
        <div className={styles.backdrop} onClick={toggleExpand} />
      )}

      <div 
        className={containerClassName}
        style={{ 
          '--default-height': defaultHeight,
          '--tab-content-max-height': isExpanded ? undefined : tabContentMaxHeight
        } as React.CSSProperties}
      >
        {/* Expand/Collapse Button */}
        {showExpandButton && (
          <button
            type="button"
            className={styles.expandButton}
            onClick={toggleExpand}
            aria-label={isExpanded ? 'Thu gọn' : 'Mở rộng'}
            title={isExpanded ? 'Thu gọn' : 'Mở rộng'}
          >
            <i className={`fas fa-${isExpanded ? 'compress' : 'expand'}`}></i>
            {isExpanded ? 'Thu gọn' : 'Mở rộng'}
          </button>
        )}

        {/* Main Content */}
        <div className={styles.content}>
          {children}
        </div>

        {/* Footer (if provided) */}
        {footer && (
          <div className={styles.footer}>
            {footer}
          </div>
        )}
      </div>
    </>
  );
};
