import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { updateTicket, fetchTicketById } from '../../../store/slices/ticketsSlice';
import {
  resetEditTicketForm,
  addToast,
} from '../../../store/slices/uiSlice';
import { Ticket, TicketPriority } from '../../../models/Ticket';
import { UUID } from '../../../models/common';
import { Input } from '../../common/Input';
import { TextArea } from '../../common/TextArea';
import { Select } from '../../common/Select';
import { Checkbox } from '../../common/Checkbox';
import { Button } from '../../common/Button';
import { FormActions } from '../../common/FormActions';
import { FileUploadArea } from '../../common/FileUploadArea';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './EditTicketForm.module.css';

export interface EditTicketFormProps {
  ticketId: UUID;
  onSuccess: () => void;
  onCancel: () => void;
}

export const EditTicketForm: React.FC<EditTicketFormProps> = ({
  ticketId,
  onSuccess,
  onCancel,
}) => {
  const dispatch = useAppDispatch();
  const selectedTicket = useAppSelector((state) => state.tickets.selectedTicket);
  const {
    loading: optLoading,
    departmentOptions,
    ticketPriorityOptions,
    ticketTypeOptions,
  } = useFormOptions('edit-ticket');

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<string>('');
  const [type, setType] = useState<string>('');
  const [departmentId, setDepartmentId] = useState<string>('');
  const [location, setLocation] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [urgent, setUrgent] = useState(false);
  const [loading, setLoading] = useState(false);
  const [loadingData, setLoadingData] = useState(true);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Fetch ticket data on mount
  useEffect(() => {
    const loadTicket = async () => {
      try {
        setLoadingData(true);
        await dispatch(fetchTicketById(ticketId)).unwrap();
      } catch (error) {
        dispatch(
          addToast({
            message: 'Không thể tải thông tin phiếu',
            type: 'error',
          })
        );
      } finally {
        setLoadingData(false);
      }
    };

    loadTicket();
  }, [dispatch, ticketId]);

  // Pre-fill form when ticket data is loaded
  useEffect(() => {
    if (selectedTicket) {
      setTitle(selectedTicket.title || '');
      setDescription(selectedTicket.description || '');
      setPriority(selectedTicket.priority || '');
      setType(selectedTicket.category || '');
      setDepartmentId(selectedTicket.departmentId || '');
      // setLocation(selectedTicket.location || '');
      // setUrgent(selectedTicket.urgent || false);
    }
  }, [selectedTicket]);

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!title.trim()) {
      newErrors.title = 'Vui lòng nhập tiêu đề';
    }

    if (!description.trim()) {
      newErrors.description = 'Vui lòng nhập mô tả';
    }

    if (!priority) {
      newErrors.priority = 'Vui lòng chọn độ ưu tiên';
    }

    if (!type) {
      newErrors.type = 'Vui lòng chọn loại phiếu';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) {
      return;
    }

    setLoading(true);

    try {
      const ticketData = {
        title:        title.trim(),
        description:  description.trim(),
        priority:     priority as TicketPriority,
        category:     type || undefined,
        departmentId: departmentId || undefined,
        location:     location.trim() || undefined,
        urgent,
        // Note: File upload is collected via FileUploadArea but not sent to API yet.
        // In production, files would need to be:
        // 1. Uploaded separately to get file URLs/IDs, or
        // 2. Sent as multipart/form-data with the ticket data
        // For now, the UI collects files for future implementation.
      };

      await dispatch(updateTicket({ id: ticketId, data: ticketData as Partial<Ticket> })).unwrap();

      dispatch(
        addToast({
          message: 'Cập nhật phiếu yêu cầu thành công',
          type: 'success',
        })
      );

      dispatch(resetEditTicketForm());
      onSuccess();
    } catch (error: any) {
      dispatch(
        addToast({
          message: error.message || 'Có lỗi xảy ra khi cập nhật phiếu',
          type: 'error',
        })
      );
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    dispatch(resetEditTicketForm());
    onCancel();
  };

  if (loadingData) {
    return (
      <div className={styles.loading}>
        <div className={styles.spinner}></div>
        <span>Đang tải dữ liệu...</span>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className={styles.form}>
      <div className={styles.formContent}>
        <Input
          label="Tiêu đề"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Nhập tiêu đề phiếu yêu cầu"
          required
          fullWidth
          error={errors.title}
        />

        <TextArea
          label="Mô tả"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Mô tả chi tiết vấn đề hoặc yêu cầu"
          required
          fullWidth
          rows={6}
          error={errors.description}
        />

        <div className={styles.row}>
          <Select
            label="Độ ưu tiên"
            value={priority}
            onChange={(e) => setPriority(e.target.value)}
            options={ticketPriorityOptions}
            placeholder={optLoading ? 'Đang tải...' : 'Chọn độ ưu tiên'}
            disabled={optLoading}
            required
            fullWidth
            error={errors.priority}
          />

          <Select
            label="Loại phiếu"
            value={type}
            onChange={(e) => setType(e.target.value)}
            options={ticketTypeOptions}
            placeholder={optLoading ? 'Đang tải...' : 'Chọn loại phiếu'}
            disabled={optLoading}
            required
            fullWidth
            error={errors.type}
          />
        </div>

        <div className={styles.row}>
          <Select
            label="Phòng ban"
            value={departmentId}
            onChange={(e) => setDepartmentId(e.target.value)}
            options={departmentOptions}
            placeholder={optLoading ? 'Đang tải danh sách...' : 'Chọn phòng ban (không bắt buộc)'}
            disabled={optLoading}
            fullWidth
          />

          <Input
            label="Vị trí"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
            placeholder="Vị trí xảy ra sự cố (không bắt buộc)"
            fullWidth
          />
        </div>

        <div className={styles.uploadSection}>
          <label className={styles.sectionLabel}>Đính kèm file</label>
          <FileUploadArea
            value={files}
            onChange={setFiles}
            maxSize={10}
            maxFiles={5}
            accept="*/*"
          />
        </div>

        <div className={styles.checkboxSection}>
          <Checkbox
            label="Gửi thông báo khẩn cấp"
            checked={urgent}
            onChange={(e) => setUrgent(e.target.checked)}
            helperText="Gửi thông báo ngay lập tức đến người phụ trách"
          />
        </div>
      </div>

      <FormActions align="end">
        <Button type="button" variant="secondary" onClick={handleReset}>
          <i className="fas fa-times"></i>
          Hủy
        </Button>
        <Button type="submit" variant="primary" loading={loading}>
          <i className="fas fa-save"></i>
          Lưu thay đổi
        </Button>
      </FormActions>
    </form>
  );
};
