import { useMemo } from 'react';
import { Task, TaskStatus } from '../models/Task';
import { User, UserRole } from '../models/User';

export interface TaskPermissions {
  canView: boolean;             // Always true for authenticated users
  canEdit: boolean;             // Owner/Creator OR Admin/Manager, NOT completed/cancelled
  canStart: boolean;            // Assignee, status === Assigned
  canUpdateProgress: boolean;   // Assignee/Collaborator, status === InProgress
  canRequestSupport: boolean;   // Assignee, status === InProgress
  canAssignCollaborator: boolean; // Manager/Admin, status === SupportRequested
  canMarkBlocked: boolean;      // Assignee, status === InProgress
  canUnblock: boolean;          // Assignee OR Manager/Admin, status === Blocked
  canSubmitForReview: boolean;  // Assignee, status === InProgress, progress === 100
  canApprove: boolean;          // Manager/Admin, status === UnderReview
  canRequestChanges: boolean;   // Manager/Admin, status === UnderReview
  canReassign: boolean;         // Manager/Admin, NOT completed/cancelled
  canCancel: boolean;           // Manager/Admin only, NOT completed/cancelled
  canClaim: boolean;            // Staff, status === Pool
  isOwner: boolean;             // currentUser.id === task.createdById
  isAssignee: boolean;          // currentUser.id === task.assigneeId
  isCollaborator: boolean;      // currentUser.id in task.collaborators
  isManager: boolean;           // role === Manager/Admin
}

/**
 * Custom hook to calculate task permissions based on user role, 
 * task ownership, assignee status, and task status (workflow-based rules)
 * 
 * Permission Rules Reference:
 * - Admin/Manager: Full control (assign, reassign, approve, cancel)
 * - Task Creator/Owner: Can view, edit (if not completed/cancelled)
 * - Assignee: Can start, update progress, request support, mark blocked, submit review
 * - Collaborators: Can view, comment, update their portion
 * 
 * @param task - The task to check permissions for
 * @param currentUser - The currently authenticated user
 * @returns Object with permission flags for all task actions
 */
export function useTaskPermissions(
  task: Task | null,
  currentUser: User | null
): TaskPermissions {
  return useMemo(() => {
    // Default: no permissions if no task or no user
    if (!task || !currentUser) {
      return {
        canView: false,
        canEdit: false,
        canStart: false,
        canUpdateProgress: false,
        canRequestSupport: false,
        canAssignCollaborator: false,
        canMarkBlocked: false,
        canUnblock: false,
        canSubmitForReview: false,
        canApprove: false,
        canRequestChanges: false,
        canReassign: false,
        canCancel: false,
        canClaim: false,
        isOwner: false,
        isAssignee: false,
        isCollaborator: false,
        isManager: false,
      };
    }

    // User identity checks
    const isOwner = task.creatorId === currentUser.id;
    const isAssignee = task.assigneeId === currentUser.id;
    const isCollaborator = task.collaborators?.some(
      (collab) => collab.userId === currentUser.id && collab.status === 'active'
    ) || false;
    const isManager = 
      currentUser.role === UserRole.Manager || 
      currentUser.role === UserRole.Admin;

    // Terminal states where most actions are disabled
    const isTerminalState = 
      task.status === TaskStatus.Completed || 
      task.status === TaskStatus.Cancelled;

    // Permission calculations based on workflow rules

    // Rule 1: Staff can only view tasks they own, are assigned to, or are a collaborator on;
    //          Manager/Admin can view all tasks in their scope (filtered server-side).
    const canView = isManager || isOwner || isAssignee || isCollaborator;

    // Rule 2: Edit permission - Owner/Creator OR Manager/Admin, NOT in terminal state
    const canEdit = 
      !isTerminalState &&
      (isOwner || isManager);

    // Rule 3: Start task - Assignee only, status === Assigned
    const canStart = 
      isAssignee && 
      task.status === TaskStatus.Assigned;

    // Rule 4: Update progress - Assignee or active Collaborator, status === InProgress
    const canUpdateProgress = 
      (isAssignee || isCollaborator) && 
      task.status === TaskStatus.InProgress;

    // Rule 5: Request support - Assignee, status === InProgress
    const canRequestSupport = 
      isAssignee && 
      task.status === TaskStatus.InProgress;

    // Rule 6: Assign collaborator - Manager/Admin, status === SupportRequested
    const canAssignCollaborator = 
      isManager && 
      task.status === TaskStatus.SupportRequested;

    // Rule 7: Mark blocked - Assignee, status === InProgress
    const canMarkBlocked = 
      isAssignee && 
      task.status === TaskStatus.InProgress;

    // Rule 8: Unblock - Assignee OR Manager/Admin, status === Blocked
    const canUnblock = 
      (isAssignee || isManager) && 
      task.status === TaskStatus.Blocked;

    // Rule 9: Submit for review - Assignee, status === InProgress, progress === 100
    const canSubmitForReview = 
      isAssignee && 
      task.status === TaskStatus.InProgress && 
      task.progress >= 100;

    // Rule 10: Approve - Manager/Admin, status === UnderReview
    const canApprove = 
      isManager && 
      task.status === TaskStatus.UnderReview;

    // Rule 11: Request changes - Manager/Admin, status === UnderReview
    const canRequestChanges = 
      isManager && 
      task.status === TaskStatus.UnderReview;

    // Rule 12: Reassign - Manager/Admin, NOT in terminal state
    const canReassign = 
      isManager && 
      !isTerminalState &&
      task.status !== TaskStatus.UnderReview; // Cannot reassign during review

    // Rule 13: Cancel - Manager/Admin only, NOT in terminal state
    const canCancel = 
      isManager && 
      !isTerminalState &&
      task.status !== TaskStatus.UnderReview; // Cannot cancel during review

    // Rule 14: Claim from pool - Staff/Manager/Admin, status === Created (Pool)
    const canClaim = 
      task.status === TaskStatus.Created && 
      task.assignmentStrategy === 'pool';
    
    return {
      canView,
      canEdit,
      canStart,
      canUpdateProgress,
      canRequestSupport,
      canAssignCollaborator,
      canMarkBlocked,
      canUnblock,
      canSubmitForReview,
      canApprove,
      canRequestChanges,
      canReassign,
      canCancel,
      canClaim,
      isOwner,
      isAssignee,
      isCollaborator,
      isManager,
    };
  }, [task, currentUser]);
}
