import React, { useEffect, useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchApprovals,
  fetchApprovalStats,
  approveApproval,
  rejectApproval,
  requestChanges,
  bulkApprovalAction,
  setFilters,
} from '../../store/slices/approvalsSlice';
import { Approval, ApprovalStatus } from '../../models/Approval';
import { ApprovalCard } from '../../components/approvals/ApprovalCard';
import {
  ApproveModal,
  RejectModal,
  RequestChangesModal,
  BulkApproveModal,
} from '../../components/approvals/ApprovalActionModals';
import { Button, TableCard, Pagination } from '../../components/common';
import { addToast } from '../../store/slices/uiSlice';
import { useResponsive } from '../../hooks/useResponsive';
import { ApprovalsStatsCards } from './components/ApprovalsStatsCards';
import { ApprovalsFilters } from './components/ApprovalsFilters';
import styles from './ApprovalsPage.module.css';

const PAGE_SIZE = 10;

const ApprovalsPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { isMobile } = useResponsive();
  const { items, stats, filters, loading, actionLoading } = useAppSelector(
    (state) => state.approvals
  );
  const [activeTab, setActiveTab] = useState<ApprovalStatus>(ApprovalStatus.Pending);
  const [typeFilter, setTypeFilter] = useState<string>('all');
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedApproval, setSelectedApproval] = useState<Approval | null>(null);
  const [approveModalOpen, setApproveModalOpen] = useState(false);
  const [rejectModalOpen, setRejectModalOpen] = useState(false);
  const [changesModalOpen, setChangesModalOpen] = useState(false);
  const [bulkApproveModalOpen, setBulkApproveModalOpen] = useState(false);

  useEffect(() => {
    dispatch(fetchApprovalStats());
    dispatch(
      fetchApprovals({
        filters: { ...filters, status: activeTab },
      })
    );
  }, [dispatch, activeTab]);

  // Reset to page 1 when filters change
  useEffect(() => { setCurrentPage(1); }, [activeTab, typeFilter]);

  const handleTabChange = (tab: ApprovalStatus) => {
    setActiveTab(tab);
    dispatch(setFilters({ ...filters, status: tab }));
  };

  // ─── Client-side type filtering + pagination ──────────────────────────────
  const filteredItems = useMemo(() => {
    let result = items.filter((a) => a.status === activeTab);
    if (typeFilter !== 'all') {
      result = result.filter((a) => a.type === typeFilter);
    }
    return result;
  }, [items, activeTab, typeFilter]);

  const totalPages = Math.ceil(filteredItems.length / PAGE_SIZE);
  const pagedItems = useMemo(
    () => filteredItems.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE),
    [filteredItems, currentPage]
  );

  const handleApprove = (approval: Approval) => {
    setSelectedApproval(approval);
    setApproveModalOpen(true);
  };

  const handleReject = (approval: Approval) => {
    setSelectedApproval(approval);
    setRejectModalOpen(true);
  };

  const handleRequestChanges = (approval: Approval) => {
    setSelectedApproval(approval);
    setChangesModalOpen(true);
  };

  const handleViewDetails = (approvalId: string) => {
    // Navigate to related entity (task, ticket, etc.)
    const approval = items.find((a) => a.id === approvalId);
    if (approval?.relatedEntityType === 'task' && approval.relatedEntityId) {
      navigate(`/tasks/${approval.relatedEntityId}`);
    }
  };

  const refreshData = () => {
    dispatch(fetchApprovalStats());
    dispatch(fetchApprovals({ filters: { ...filters, status: activeTab } }));
  };

  const confirmApprove = async (note?: string) => {
    if (!selectedApproval) return;
    try {
      await dispatch(
        approveApproval({ approvalId: selectedApproval.id, note })
      ).unwrap();
      dispatch(addToast({ message: 'Đã chấp nhận yêu cầu thành công', type: 'success' }));
      setApproveModalOpen(false);
      setSelectedApproval(null);
      refreshData();
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Không thể chấp nhận yêu cầu. Vui lòng thử lại!';
      dispatch(addToast({ message, type: 'error' }));
    }
  };

  const confirmReject = async (reason: string) => {
    if (!selectedApproval) return;
    try {
      await dispatch(
        rejectApproval({ approvalId: selectedApproval.id, reason })
      ).unwrap();
      dispatch(addToast({ message: 'Đã từ chối yêu cầu', type: 'success' }));
      setRejectModalOpen(false);
      setSelectedApproval(null);
      refreshData();
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Không thể từ chối yêu cầu. Vui lòng thử lại!';
      dispatch(addToast({ message, type: 'error' }));
    }
  };

  const confirmRequestChanges = async (changes: string) => {
    if (!selectedApproval) return;
    try {
      await dispatch(
        requestChanges({ approvalId: selectedApproval.id, changes })
      ).unwrap();
      dispatch(addToast({ message: 'Đã gửi yêu cầu sửa đổi', type: 'success' }));
      setChangesModalOpen(false);
      setSelectedApproval(null);
      dispatch(fetchApprovals({ filters: { ...filters, status: activeTab } }));
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Không thể gửi yêu cầu sửa đổi. Vui lòng thử lại!';
      dispatch(addToast({ message, type: 'error' }));
    }
  };

  const confirmBulkApprove = async (note?: string) => {
    const pendingApprovals = items.filter((a) => a.status === ApprovalStatus.Pending);
    const approvalIds = pendingApprovals.map((a) => a.id);
    if (approvalIds.length === 0) {
      dispatch(addToast({ message: 'Không có yêu cầu nào để phê duyệt', type: 'warning' }));
      return;
    }
    try {
      await dispatch(
        bulkApprovalAction({ approvalIds, action: 'approve', note })
      ).unwrap();
      dispatch(addToast({ message: `Đã chấp nhận ${approvalIds.length} yêu cầu`, type: 'success' }));
      setBulkApproveModalOpen(false);
      refreshData();
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Không thể thực hiện phê duyệt hàng loạt. Vui lòng thử lại!';
      dispatch(addToast({ message, type: 'error' }));
    }
  };

  const pendingCount       = stats?.pending       ?? 0;
  const approvedTodayCount = stats?.approvedToday ?? 0;
  const rejectedTodayCount = stats?.rejectedToday ?? 0;

  return (
    <div className={styles.page}>

      {/* 1. Page Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-check-double" />
          Phê duyệt
        </h1>
        {pendingCount > 0 && (
          <Button variant="success" onClick={() => setBulkApproveModalOpen(true)}>
            <i className="fas fa-check-double" />
            {!isMobile && ` Chấp nhận tất cả (${pendingCount})`}
          </Button>
        )}
      </div>

      {/* 2. Stats Cards */}
      <ApprovalsStatsCards stats={stats} loading={loading} />

      {/* 3. TableCard: Filters + List + Pagination */}
      <TableCard
        header={
          <ApprovalsFilters
            activeTab={activeTab}
            onTabChange={handleTabChange}
            typeFilter={typeFilter}
            onTypeChange={setTypeFilter}
            pendingCount={pendingCount}
            approvedTodayCount={approvedTodayCount}
            rejectedTodayCount={rejectedTodayCount}
          />
        }
        footer={
          !loading && filteredItems.length > 0 ? (
            <Pagination
              currentPage={currentPage}
              totalPages={totalPages}
              totalCount={filteredItems.length}
              pageSize={PAGE_SIZE}
              onPageChange={setCurrentPage}
            />
          ) : undefined
        }
      >
        {loading && (
          <div className={styles.loading}>
            <i className="fas fa-spinner fa-spin" /> Đang tải...
          </div>
        )}

        {!loading && pagedItems.length === 0 && (
          <div className={styles.empty}>
            <i className="fas fa-inbox" />
            <p>Không có yêu cầu phê duyệt nào</p>
          </div>
        )}

        {!loading && pagedItems.length > 0 && (
          <div className={styles.cardList}>
            {pagedItems.map((approval) => (
              <ApprovalCard
                key={approval.id}
                approval={approval}
                onApprove={() => handleApprove(approval)}
                onReject={() => handleReject(approval)}
                onRequestChanges={
                  activeTab === ApprovalStatus.Pending
                    ? () => handleRequestChanges(approval)
                    : undefined
                }
                onViewDetails={() => handleViewDetails(approval.id)}
              />
            ))}
          </div>
        )}
      </TableCard>

      {/* Modals */}
      <ApproveModal
        isOpen={approveModalOpen}
        onClose={() => { setApproveModalOpen(false); setSelectedApproval(null); }}
        onConfirm={confirmApprove}
        approvalTitle={selectedApproval?.title || ''}
        loading={actionLoading}
      />
      <RejectModal
        isOpen={rejectModalOpen}
        onClose={() => { setRejectModalOpen(false); setSelectedApproval(null); }}
        onConfirm={confirmReject}
        approvalTitle={selectedApproval?.title || ''}
        loading={actionLoading}
      />
      <RequestChangesModal
        isOpen={changesModalOpen}
        onClose={() => { setChangesModalOpen(false); setSelectedApproval(null); }}
        onConfirm={confirmRequestChanges}
        approvalTitle={selectedApproval?.title || ''}
        loading={actionLoading}
      />
      <BulkApproveModal
        isOpen={bulkApproveModalOpen}
        onClose={() => setBulkApproveModalOpen(false)}
        onConfirm={confirmBulkApprove}
        count={pendingCount}
        loading={actionLoading}
      />
    </div>
  );
};

export default ApprovalsPage;
