/**
 * AccountsManagementPage
 * Admin page for listing accounts, viewing details, assigning / removing packages.
 */
import React, { useState, useEffect, useCallback } from 'react';
import { adminService } from '../../services/admin';
import type {
  BffAccountListItemDto,
  BffAccountDetailDto,
  BffFeaturePackageDto,
} from '../../services/admin/responseModel';
import { Slideout } from '../../components/common/Slideout';
import { useResponsive } from '../../hooks/useResponsive';
import { useAppToast } from '../../hooks/useAppToast';
import styles from './AccountsManagementPage.module.css';

// ─────────────────────────────────────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────────────────────────────────────

const ROLE_LABELS: Record<string, string> = {
  admin:   'Quản trị viên',
  manager: 'Quản lý',
  staff:   'Nhân viên',
};

const PAGE_SIZE = 20;

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

const AccountsManagementPage: React.FC = () => {
  const { isMobile, isTablet } = useResponsive();
  const toast = useAppToast();
  const slideoutWidth = isMobile ? '100%' : isTablet ? '520px' : '640px';

  // ── List state ────────────────────────────────────────────────────────────
  const [accounts, setAccounts]         = useState<BffAccountListItemDto[]>([]);
  const [totalCount, setTotalCount]     = useState(0);
  const [page, setPage]                 = useState(1);
  const [loading, setLoading]           = useState(true);
  const [search, setSearch]             = useState('');
  const [roleFilter, setRoleFilter]     = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'inactive'>('all');

  // ── Detail slideout state ──────────────────────────────────────────────────
  const [selectedAccount, setSelectedAccount]   = useState<BffAccountDetailDto | null>(null);
  const [detailOpen, setDetailOpen]             = useState(false);
  const [detailLoading, setDetailLoading]       = useState(false);

  // ── Package assignment state ───────────────────────────────────────────────
  const [allPackages, setAllPackages]           = useState<BffFeaturePackageDto[]>([]);
  const [assignOpen, setAssignOpen]             = useState(false);
  const [assignPackageId, setAssignPackageId]   = useState('');
  const [assignStartDate, setAssignStartDate]   = useState(() => new Date().toISOString().slice(0, 10));
  const [assignExpiresAt, setAssignExpiresAt]   = useState('');
  const [assignNotes, setAssignNotes]           = useState('');
  const [assigning, setAssigning]               = useState(false);

  // ── Status toggle state ────────────────────────────────────────────────────
  const [statusTargetId, setStatusTargetId]     = useState<string | null>(null);
  const [statusTargetActive, setStatusTargetActive] = useState(false);
  const [statusChanging, setStatusChanging]     = useState(false);

  // ── Load accounts ──────────────────────────────────────────────────────────
  const loadAccounts = useCallback(async () => {
    setLoading(true);
    try {
      const isActive = statusFilter === 'all' ? undefined : statusFilter === 'active';
      const result = await adminService.getAccounts({
        search:   search || undefined,
        role:     roleFilter || undefined,
        isActive,
        page,
        pageSize: PAGE_SIZE,
      });
      setAccounts(result.items);
      setTotalCount(result.totalCount);
    } catch {
      toast.error('Không thể tải danh sách tài khoản');
    } finally {
      setLoading(false);
    }
  }, [search, roleFilter, statusFilter, page]);

  useEffect(() => { loadAccounts(); }, [loadAccounts]);

  // Load all packages once (for assign form)
  useEffect(() => {
    adminService.getPackages().then(setAllPackages).catch(() => {});
  }, []);

  // ── Open detail ────────────────────────────────────────────────────────────
  const openDetail = useCallback(async (account: BffAccountListItemDto) => {
    setDetailOpen(true);
    setDetailLoading(true);
    setSelectedAccount(null);
    try {
      const detail = await adminService.getAccountDetail(account.id);
      setSelectedAccount(detail);
    } catch {
      toast.error('Không thể tải thông tin tài khoản');
      setDetailOpen(false);
    } finally {
      setDetailLoading(false);
    }
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const closeDetail = () => {
    setDetailOpen(false);
    setSelectedAccount(null);
    setAssignOpen(false);
    resetAssignForm();
  };

  // ── Assign package ─────────────────────────────────────────────────────────
  const resetAssignForm = () => {
    setAssignPackageId('');
    setAssignStartDate(new Date().toISOString().slice(0, 10));
    setAssignExpiresAt('');
    setAssignNotes('');
  };

  const handleAssignPackage = async () => {
    if (!selectedAccount || !assignPackageId) return;
    setAssigning(true);
    try {
      const assignment = await adminService.assignPackage(selectedAccount.id, {
        packageId: assignPackageId,
        expiresAt: assignExpiresAt ? new Date(assignExpiresAt).toISOString() : null,
        notes: assignNotes || undefined,
      });
      setSelectedAccount((prev) =>
        prev ? { ...prev, packages: [...prev.packages, assignment] } : prev,
      );
      setAccounts((prev) =>
        prev.map((a) =>
          a.id === selectedAccount.id
            ? { ...a, activePackageCount: a.activePackageCount + 1 }
            : a,
        ),
      );
      toast.success('Đã gán gói quyền thành công');
      setAssignOpen(false);
      resetAssignForm();
    } catch {
      toast.error('Không thể gán gói quyền');
    } finally {
      setAssigning(false);
    }
  };

  // ── Remove package ─────────────────────────────────────────────────────────
  const handleRemovePackage = async (assignmentId: string) => {
    if (!selectedAccount) return;
    try {
      await adminService.removePackage(selectedAccount.id, assignmentId);
      setSelectedAccount((prev) =>
        prev ? { ...prev, packages: prev.packages.filter((p) => p.assignmentId !== assignmentId) } : prev,
      );
      setAccounts((prev) =>
        prev.map((a) =>
          a.id === selectedAccount.id
            ? { ...a, activePackageCount: Math.max(0, a.activePackageCount - 1) }
            : a,
        ),
      );
      toast.success('Đã xóa gói quyền');
    } catch {
      toast.error('Không thể xóa gói quyền');
    }
  };

  // ── Status change ──────────────────────────────────────────────────────────
  const confirmStatusChange = (id: string, currentActive: boolean) => {
    setStatusTargetId(id);
    setStatusTargetActive(currentActive);
  };

  const handleStatusChange = async () => {
    if (!statusTargetId) return;
    setStatusChanging(true);
    const newStatus = !statusTargetActive;
    try {
      await adminService.setAccountStatus(statusTargetId, { isActive: newStatus });
      setAccounts((prev) =>
        prev.map((a) => (a.id === statusTargetId ? { ...a, isActive: newStatus } : a)),
      );
      if (selectedAccount?.id === statusTargetId) {
        setSelectedAccount((prev) => prev ? { ...prev, isActive: newStatus } : prev);
      }
      toast.success(newStatus ? 'Đã kích hoạt tài khoản' : 'Đã vô hiệu hóa tài khoản');
      setStatusTargetId(null);
    } catch {
      toast.error('Không thể thay đổi trạng thái tài khoản');
    } finally {
      setStatusChanging(false);
    }
  };

  // ── Search debounce ────────────────────────────────────────────────────────
  const handleSearch = (val: string) => {
    setSearch(val);
    setPage(1);
  };

  const totalPages = Math.ceil(totalCount / PAGE_SIZE);

  // ─────────────────────────────────────────────────────────────────────────
  // Render
  // ─────────────────────────────────────────────────────────────────────────

  return (
    <div className={styles.page}>
      {/* Header */}
      <div className={styles.header}>
        <div className={styles.headerLeft}>
          <h1 className={styles.title}>
            <i className="fas fa-users-cog" />
            Quản lý tài khoản
          </h1>
          <span className={styles.subtitle}>
            Quản lý người dùng và gán gói quyền
          </span>
        </div>
      </div>

      {/* Filters */}
      <div className={styles.filters}>
        <div className={styles.searchWrapper}>
          <i className={`fas fa-search ${styles.searchIcon}`} />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Tìm theo tên, email, username..."
            value={search}
            onChange={(e) => handleSearch(e.target.value)}
          />
        </div>
        <select
          className={styles.filterSelect}
          value={roleFilter}
          onChange={(e) => { setRoleFilter(e.target.value); setPage(1); }}
        >
          <option value="">Tất cả vai trò</option>
          <option value="staff">Nhân viên</option>
          <option value="manager">Quản lý</option>
          <option value="admin">Quản trị viên</option>
        </select>
        <select
          className={styles.filterSelect}
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value as typeof statusFilter); setPage(1); }}
        >
          <option value="all">Tất cả trạng thái</option>
          <option value="active">Hoạt động</option>
          <option value="inactive">Không hoạt động</option>
        </select>
      </div>

      {/* Table */}
      <div className={styles.card}>
        {loading ? (
          <div className={styles.loadingState}>
            <i className="fas fa-spinner fa-spin" />
            <span>Đang tải dữ liệu...</span>
          </div>
        ) : accounts.length === 0 ? (
          <div className={styles.emptyState}>
            <i className="fas fa-user-slash" />
            <p>Không tìm thấy tài khoản nào</p>
          </div>
        ) : (
          <div className={styles.tableWrapper}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>Người dùng</th>
                  <th>Vai trò</th>
                  <th>Gói quyền</th>
                  <th>Trạng thái</th>
                  <th className={styles.actionsCol}>Hành động</th>
                </tr>
              </thead>
              <tbody>
                {accounts.map((acc) => (
                  <tr
                    key={acc.id}
                    className={!acc.isActive ? styles.inactiveRow : ''}
                    onClick={() => openDetail(acc)}
                    style={{ cursor: 'pointer' }}
                  >
                    <td>
                      <div className={styles.userCell}>
                        <div className={styles.avatar}>
                          {acc.fullName.charAt(0).toUpperCase()}
                        </div>
                        <div>
                          <div className={styles.userName}>{acc.fullName}</div>
                          <div className={styles.userSub}>
                            @{acc.username} &middot; {acc.email}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td>
                      <span className={`${styles.roleBadge} ${styles[`role_${acc.role}`]}`}>
                        {ROLE_LABELS[acc.role] ?? acc.role}
                      </span>
                    </td>
                    <td>
                      <span className={styles.packageCount}>
                        <i className="fas fa-cube" />
                        {acc.activePackageCount} gói
                      </span>
                    </td>
                    <td>
                      <span className={`${styles.statusBadge} ${acc.isActive ? styles.active : styles.inactive}`}>
                        {acc.isActive ? 'Hoạt động' : 'Không hoạt động'}
                      </span>
                    </td>
                    <td className={styles.actionsCell} onClick={(e) => e.stopPropagation()}>
                      <button
                        className={styles.viewBtn}
                        onClick={() => openDetail(acc)}
                        title="Xem chi tiết"
                      >
                        <i className="fas fa-eye" />
                      </button>
                      <button
                        className={acc.isActive ? styles.deactivateBtn : styles.activateBtn}
                        onClick={() => confirmStatusChange(acc.id, acc.isActive)}
                        title={acc.isActive ? 'Vô hiệu hóa' : 'Kích hoạt'}
                      >
                        <i className={acc.isActive ? 'fas fa-ban' : 'fas fa-check-circle'} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Pagination */}
        {totalPages > 1 && (
          <div className={styles.pagination}>
            <span className={styles.paginationInfo}>
              {(page - 1) * PAGE_SIZE + 1}–{Math.min(page * PAGE_SIZE, totalCount)} / {totalCount} tài khoản
            </span>
            <div className={styles.paginationBtns}>
              <button
                className={styles.pageBtn}
                disabled={page <= 1}
                onClick={() => setPage((p) => p - 1)}
              >
                <i className="fas fa-chevron-left" />
              </button>
              <span className={styles.pageNum}>{page} / {totalPages}</span>
              <button
                className={styles.pageBtn}
                disabled={page >= totalPages}
                onClick={() => setPage((p) => p + 1)}
              >
                <i className="fas fa-chevron-right" />
              </button>
            </div>
          </div>
        )}
      </div>

      {/* ── Account Detail Slideout ── */}
      <Slideout
        isOpen={detailOpen}
        onClose={closeDetail}
        title={
          <span className={styles.slideoutTitle}>
            <i className="fas fa-id-card" style={{ color: 'var(--primary-color)' }} />
            Chi tiết tài khoản
          </span>
        }
        width={slideoutWidth}
        customFooter={
          <button className={styles.cancelBtn} onClick={closeDetail}>
            Đóng
          </button>
        }
      >
        {detailLoading ? (
          <div className={styles.loadingState}>
            <i className="fas fa-spinner fa-spin" />
            <span>Đang tải...</span>
          </div>
        ) : selectedAccount ? (
          <div className={styles.detailContent}>
            {/* User info */}
            <div className={styles.detailHeader}>
              <div className={styles.detailAvatar}>
                {selectedAccount.avatarUrl
                  ? <img src={selectedAccount.avatarUrl} alt={selectedAccount.fullName} className={styles.detailAvatarImg} />
                  : selectedAccount.fullName.charAt(0).toUpperCase()
                }
              </div>
              <div>
                <div className={styles.detailName}>{selectedAccount.fullName}</div>
                <div className={styles.detailEmail}>
                  {selectedAccount.email ?? selectedAccount.phone ?? `@${selectedAccount.username}`}
                </div>
                <div className={styles.detailMeta}>
                  {(selectedAccount.roles?.length ? selectedAccount.roles : [selectedAccount.role]).map((r) => (
                    <span key={r} className={`${styles.roleBadge} ${styles[`role_${r?.toLowerCase()}`]}`}>
                      {ROLE_LABELS[r?.toLowerCase()] ?? r}
                    </span>
                  ))}
                  <span className={`${styles.statusBadge} ${selectedAccount.isActive ? styles.active : styles.inactive}`}>
                    {selectedAccount.isActive ? 'Hoạt động' : 'Không hoạt động'}
                  </span>
                </div>
              </div>
            </div>

            <div className={styles.infoGrid}>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-user" /> Username</span>
                <span className={styles.infoValue}>@{selectedAccount.username}</span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-id-badge" /> Mã nhân viên</span>
                <span className={styles.infoValue}>{selectedAccount.employeeId ?? '—'}</span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-phone" /> Số điện thoại</span>
                <span className={styles.infoValue}>{selectedAccount.phone ?? '—'}</span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-id-card" /> CCCD / CMND</span>
                <span className={styles.infoValue}>{selectedAccount.citizenId ?? '—'}</span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-birthday-cake" /> Ngày sinh</span>
                <span className={styles.infoValue}>
                  {selectedAccount.dateOfBirth && selectedAccount.dateOfBirth !== '0001-01-01T00:00:00.000Z'
                    ? new Date(selectedAccount.dateOfBirth).toLocaleDateString('vi-VN')
                    : '—'
                  }
                </span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-venus-mars" /> Giới tính</span>
                <span className={styles.infoValue}>
                  {selectedAccount.gender === 'Male' ? 'Nam'
                    : selectedAccount.gender === 'Female' ? 'Nữ'
                    : selectedAccount.gender ?? '—'}
                </span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-envelope" /> Email</span>
                <span className={styles.infoValue}>{selectedAccount.email ?? '—'}</span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-envelope-open-text" /> Xác nhận email</span>
                <span className={styles.infoValue}>
                  {selectedAccount.isEmailConfirmed
                    ? <span className={styles.confirmedBadge}><i className="fas fa-check" /> Đã xác nhận</span>
                    : <span className={styles.unconfirmedBadge}><i className="fas fa-clock" /> Chưa xác nhận</span>
                  }
                </span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-calendar-plus" /> Ngày tạo</span>
                <span className={styles.infoValue}>
                  {new Date(selectedAccount.createdAt).toLocaleDateString('vi-VN')}
                </span>
              </div>
              <div className={styles.infoItem}>
                <span className={styles.infoLabel}><i className="fas fa-sign-in-alt" /> Đăng nhập lần cuối</span>
                <span className={styles.infoValue}>
                  {selectedAccount.lastLoginAt
                    ? new Date(selectedAccount.lastLoginAt).toLocaleString('vi-VN')
                    : '—'
                  }
                </span>
              </div>
            </div>

            {/* Packages section */}
            <div className={styles.sectionHeader}>
              <span className={styles.sectionTitle}>
                <i className="fas fa-cube" /> Gói quyền ({selectedAccount.packages.length})
              </span>
              <button
                className={styles.assignBtn}
                onClick={() => setAssignOpen(true)}
              >
                <i className="fas fa-plus" /> Gán gói
              </button>
            </div>

            {selectedAccount.packages.length === 0 ? (
              <div className={styles.noPackages}>
                <i className="fas fa-box-open" />
                <span>Chưa có gói quyền nào</span>
              </div>
            ) : (
              <div className={styles.packageList}>
                {selectedAccount.packages.map((pkg) => (
                  <div key={pkg.assignmentId} className={styles.packageCard}>
                    <div className={styles.packageCardLeft}>
                      <div className={styles.packageCode}>{pkg.packageCode}</div>
                      <div className={styles.packageName}>{pkg.packageName}</div>
                      <div className={styles.packageDates}>
                        <span>
                          <i className="fas fa-play-circle" />
                          {new Date(pkg.startDate).toLocaleDateString('vi-VN')}
                        </span>
                        {pkg.expiresAt && (
                          <span>
                            <i className="fas fa-stop-circle" />
                            {new Date(pkg.expiresAt).toLocaleDateString('vi-VN')}
                          </span>
                        )}
                        {pkg.assignedBy && (
                          <span>
                            <i className="fas fa-user-check" />
                            {pkg.assignedBy}
                          </span>
                        )}
                      </div>
                    </div>
                    <button
                      className={styles.removePackageBtn}
                      onClick={() => handleRemovePackage(pkg.assignmentId)}
                      title="Xóa gói"
                    >
                      <i className="fas fa-times" />
                    </button>
                  </div>
                ))}
              </div>
            )}

            {/* Assign package mini-form */}
            {assignOpen && (
              <div className={styles.assignForm}>
                <div className={styles.assignFormTitle}>
                  <i className="fas fa-plus-circle" /> Gán gói quyền mới
                </div>
                <div className={styles.formGroup}>
                  <label className={styles.label}>Gói quyền <span className={styles.required}>*</span></label>
                  <select
                    className={styles.select}
                    value={assignPackageId}
                    onChange={(e) => setAssignPackageId(e.target.value)}
                  >
                    <option value="">— Chọn gói —</option>
                    {allPackages
                      .filter((p) => !selectedAccount.packages.some((ap) => ap.packageId === p.id))
                      .map((p) => (
                        <option key={p.id} value={p.id}>{p.code} – {p.name}</option>
                      ))
                    }
                  </select>
                </div>
                <div className={styles.formRow}>
                  <div className={styles.formGroup}>
                    <label className={styles.label}>Ngày bắt đầu <span className={styles.required}>*</span></label>
                    <input
                      type="date"
                      className={styles.input}
                      value={assignStartDate}
                      onChange={(e) => setAssignStartDate(e.target.value)}
                    />
                  </div>
                  <div className={styles.formGroup}>
                    <label className={styles.label}>Ngày hết hạn <span className={styles.hint}>(tùy chọn)</span></label>
                    <input
                      type="date"
                      className={styles.input}
                      value={assignExpiresAt}
                      onChange={(e) => setAssignExpiresAt(e.target.value)}
                    />
                  </div>
                </div>
                <div className={styles.formGroup}>
                  <label className={styles.label}>Ghi chú</label>
                  <input
                    type="text"
                    className={styles.input}
                    value={assignNotes}
                    onChange={(e) => setAssignNotes(e.target.value)}
                    placeholder="Ghi chú tùy chọn..."
                  />
                </div>
                <div className={styles.assignFormActions}>
                  <button
                    className={styles.cancelSmallBtn}
                    onClick={() => { setAssignOpen(false); resetAssignForm(); }}
                    disabled={assigning}
                  >
                    Hủy
                  </button>
                  <button
                    className={styles.confirmAssignBtn}
                    onClick={handleAssignPackage}
                    disabled={assigning || !assignPackageId}
                  >
                    {assigning
                      ? <><i className="fas fa-spinner fa-spin" /> Đang gán...</>
                      : <><i className="fas fa-check" /> Xác nhận gán</>
                    }
                  </button>
                </div>
              </div>
            )}
          </div>
        ) : null}
      </Slideout>

      {/* ── Status Change Confirm Slideout ── */}
      <Slideout
        isOpen={!!statusTargetId}
        onClose={() => { if (!statusChanging) setStatusTargetId(null); }}
        title={statusTargetActive ? 'Xác nhận vô hiệu hóa' : 'Xác nhận kích hoạt'}
        width="420px"
        customFooter={
          <>
            <button
              className={styles.cancelBtn}
              onClick={() => setStatusTargetId(null)}
              disabled={statusChanging}
            >
              Hủy
            </button>
            <button
              className={statusTargetActive ? styles.deactivateConfirmBtn : styles.activateConfirmBtn}
              onClick={handleStatusChange}
              disabled={statusChanging}
            >
              {statusChanging
                ? <><i className="fas fa-spinner fa-spin" /> Đang xử lý...</>
                : statusTargetActive
                ? <><i className="fas fa-ban" /> Vô hiệu hóa</>
                : <><i className="fas fa-check-circle" /> Kích hoạt</>
              }
            </button>
          </>
        }
      >
        <div className={styles.confirmBody}>
          <div className={`${styles.confirmIcon} ${statusTargetActive ? styles.dangerIcon : styles.successIcon}`}>
            <i className={statusTargetActive ? 'fas fa-ban' : 'fas fa-check-circle'} />
          </div>
          <h3 className={styles.confirmTitle}>
            {statusTargetActive ? 'Vô hiệu hóa tài khoản?' : 'Kích hoạt tài khoản?'}
          </h3>
          <p className={styles.confirmText}>
            {statusTargetActive
              ? 'Người dùng sẽ không thể đăng nhập cho đến khi được kích hoạt lại.'
              : 'Người dùng sẽ có thể đăng nhập trở lại sau khi kích hoạt.'}
          </p>
        </div>
      </Slideout>
    </div>
  );
};

export default AccountsManagementPage;
