import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../../store/hooks';
import { closeTicket } from '../../../store/slices/ticketsSlice';
import { addToast } from '../../../store/slices/uiSlice';
import { UUID } from '../../../models/common';
import { Slideout } from '../../common/Slideout';
import { TextArea } from '../../common/TextArea';
import styles from './CloseTicketModal.module.css';

export interface CloseTicketModalProps {
  isOpen: boolean;
  ticketId: UUID;
  onClose: () => void;
  onSuccess?: () => void;
}

export const CloseTicketModal: React.FC<CloseTicketModalProps> = ({
  isOpen,
  ticketId,
  onClose,
  onSuccess,
}) => {
  const dispatch = useAppDispatch();
  const ticket   = useAppSelector((s) => s.tickets.selectedTicket);
  const [note, setNote] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isOpen) setNote('');
  }, [isOpen]);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      await dispatch(closeTicket({ ticketId, note: note.trim() || undefined })).unwrap();
      dispatch(addToast({ message: 'Đóng phiếu yêu cầu thành công', type: 'success' }));
      onClose();
      onSuccess?.();
    } catch (err: any) {
      dispatch(addToast({ message: err?.message || 'Không thể đóng phiếu yêu cầu', type: 'error' }));
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    setNote('');
    onClose();
  };

  return (
    <Slideout
      isOpen={isOpen}
      onClose={handleCancel}
      title="Đóng Phiếu Yêu Cầu"
      width="520px"
      footer={{
        leftLabel: 'Hủy',
        leftAction: handleCancel,
        leftDisabled: loading,
        rightLabel: loading ? 'Đang đóng...' : 'Xác nhận đóng',
        rightAction: handleSubmit,
        rightDisabled: loading,
      }}
    >
      <div className={styles.form}>
        {ticket && (
          <div className={styles.summary}>
            <p className={styles.summaryLabel}>Phiếu yêu cầu</p>
            <p className={styles.summaryTitle}>{ticket.title}</p>
          </div>
        )}

        <div className={styles.field}>
          <label className={styles.label}>Ghi chú (tùy chọn)</label>
          <TextArea
            value={note}
            onChange={(e) => setNote(e.target.value)}
            placeholder="Ghi chú bổ sung khi đóng phiếu (nếu có)..."
            rows={4}
            disabled={loading}
          />
          <span className={styles.hint}>Không bắt buộc — thêm ghi chú nếu cần thiết.</span>
        </div>
      </div>
    </Slideout>
  );
};
